package com.bingobrazilchat;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BingoBrazilChatConfig.GROUP)
public interface BingoBrazilChatConfig extends Config
{
	String GROUP = "bingobrazilchat";

	@ConfigItem(
		keyName = "sharedToken",
		name = "Event token",
		description = "The token your event organiser gave you. The plugin does nothing at all "
			+ "until this is filled in - with no token it never contacts the network.",
		position = 1,
		secret = true
	)
	default String sharedToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "captureScreenshot",
		name = "Attach screenshots",
		description = "Take a screenshot when a listed drop is broadcast and send it as proof. "
			+ "Turning this off still records the drop, just without an image.",
		position = 3
	)
	default boolean captureScreenshot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "screenshotScale",
		name = "Screenshot size",
		description = "Scale applied before upload, as a percentage of the client size. Lower "
			+ "means a smaller upload.",
		position = 4
	)
	@net.runelite.client.config.Range(min = 25, max = 100)
	default int screenshotScalePercent()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "enableObserverReports",
		name = "Report other players' drops",
		description = "Report listed drops broadcast by anyone on the event roster, not just your "
			+ "own. Leaving this on means a drop still gets recorded when the person who got it "
			+ "isn't running the plugin.",
		position = 5
	)
	default boolean enableObserverReports()
	{
		return true;
	}

	@ConfigItem(
		keyName = "announceInChat",
		name = "Confirm in chat",
		description = "Print a local game message when a drop has been recorded on the site.",
		position = 6
	)
	default boolean announceInChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "debugLogUnmatched",
		name = "Log unrecognised broadcasts",
		description = "Write clan broadcasts that look like drops but could not be parsed to the "
			+ "client log. Useful for reporting a missed item to the event organiser.",
		position = 7
	)
	default boolean debugLogUnmatched()
	{
		return false;
	}

	@ConfigSection(
		name = "<html>This plugin sends data to the event site<br>"
			+ "When a listed raid drop is broadcast in your clan,<br>"
			+ "it sends the player name, the item, and a screenshot<br>"
			+ "to your event organiser's BrazilChat site.<br>"
			+ "Nothing is sent until you enter an event token.</html>",
		description = "Bingo BrazilChat reports listed clan drop broadcasts to the BrazilChat "
			+ "event site so they score on the team leaderboard automatically. It sends the "
			+ "dropper's name, the item name, the broadcast text and a screenshot. It sends "
			+ "nothing at all while the event token is empty.",
		position = 98,
		closedByDefault = true
	)
	String privacySection = "privacySection";

	@ConfigSection(
		name = "<html>Open the side panel for the live scoreboard<br>"
			+ "Click the Bingo BrazilChat icon on the right<br>"
			+ "to see team standings and your pending drops</html>",
		description = "The side panel shows the live team leaderboard, a countdown to the event "
			+ "start or end, and anything this client has queued to send.",
		position = 99,
		closedByDefault = true
	)
	String panelSection = "panelSection";
}

package com.bingobrazilchat;

import com.bingobrazilchat.api.ApiCallback;
import com.bingobrazilchat.api.ApiDtos;
import com.bingobrazilchat.api.ApiException;
import com.bingobrazilchat.api.BingoApiClient;
import com.bingobrazilchat.capture.ScreenshotService;
import com.bingobrazilchat.catalog.AliasResource;
import com.bingobrazilchat.catalog.CatalogItem;
import com.bingobrazilchat.catalog.DropCatalog;
import com.bingobrazilchat.chat.ChatBroadcastListener;
import com.bingobrazilchat.event.EventState;
import com.bingobrazilchat.event.ServerClock;
import com.bingobrazilchat.submit.Backoff;
import com.bingobrazilchat.submit.DropPipeline;
import com.bingobrazilchat.submit.QueuePersistence;
import com.bingobrazilchat.submit.QueuedSubmission;
import com.bingobrazilchat.submit.SubmissionQueue;
import com.bingobrazilchat.ui.BingoPanel;
import com.bingobrazilchat.ui.PanelState;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Reports listed raid drops from clan broadcasts to a BrazilChat event.
 *
 * <p><b>Consent gate:</b> this plugin sends data off the machine, which the other plugins in this
 * account do not. It is inert until the player enters an event token, so a fresh install makes no
 * network requests at all.
 *
 * <p><b>Threading:</b> chat handling is on the client thread; every piece of slow or stateful work
 * runs on {@link #executor}, a single thread owned by this plugin. RuneLite's own injected
 * {@code ScheduledExecutorService} is deliberately not used -- it is one thread shared by every
 * plugin in the client, and a PNG encode there would stall everyone else.
 */
@Slf4j
@PluginDescriptor(
	name = "Bingo BrazilChat",
	description = "Reports listed raid drops from clan broadcasts to a BrazilChat event",
	tags = {"bingo", "clan", "broadcast", "drop", "raids", "event", "leaderboard"}
)
public class BingoBrazilChatPlugin extends Plugin
{
	private static final long CONFIG_RETRY_SECONDS = 60L;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BingoBrazilChatConfig config;

	@Inject
	private EventBus eventBus;

	@Inject
	private Gson gson;

	@Inject
	private BingoApiClient api;

	@Inject
	private ScreenshotService screenshots;

	private ScheduledExecutorService executor;
	private SubmissionQueue queue;
	private QueuePersistence persistence;
	private DropPipeline pipeline;
	private ChatBroadcastListener chatListener;
	private BingoPanel panel;
	private NavigationButton navButton;

	private final ServerClock serverClock = new ServerClock();

	private AliasResource.Loaded bakedAliases;

	/** Replaced wholesale on each refresh so readers always see one consistent view. */
	private volatile EventState eventState;

	private volatile PanelState.Connection connection = PanelState.Connection.NOT_CONFIGURED;
	private volatile String connectionDetail;
	private volatile List<ApiDtos.TeamRow> teams = Collections.emptyList();
	private volatile List<QueuedSubmission> queueSnapshot = Collections.emptyList();
	private volatile String leaderboardEtag;

	@Override
	protected void startUp() throws Exception
	{
		bakedAliases = AliasResource.load(gson);

		executor = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread t = new Thread(r, "bingo-brazilchat");
			t.setDaemon(true);
			return t;
		});

		persistence = new QueuePersistence(configManager, gson);
		queue = new SubmissionQueue(executor, api, persistence, new Backoff(),
			snapshot ->
			{
				queueSnapshot = snapshot;
				pushPanelState();
			},
			this::announceRecorded);
		pipeline = new DropPipeline(executor, screenshots, queue, persistence, config, serverClock);
		chatListener = new ChatBroadcastListener(client, config, pipeline, () -> eventState);

		panel = new BingoPanel(() -> queue.clearTerminal());

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/bingobrazilchat/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Bingo BrazilChat")
			.icon(icon)
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		eventBus.register(chatListener);
		queue.start();

		scheduleConfigRefresh(0L);
		scheduleLeaderboardRefresh();
		pushPanelState();
	}

	@Override
	protected void shutDown()
	{
		if (chatListener != null)
		{
			eventBus.unregister(chatListener);
			chatListener = null;
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (panel != null)
		{
			panel.shutdown();
			panel = null;
		}
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
		eventState = null;
		teams = Collections.emptyList();
	}

	@Provides
	BingoBrazilChatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BingoBrazilChatConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BingoBrazilChatConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		// A newly pasted token should take effect immediately rather than on the next poll --
		// otherwise the plugin looks broken for five minutes after setup.
		if ("sharedToken".equals(event.getKey()))
		{
			leaderboardEtag = null;
			scheduleConfigRefresh(0L);
		}
	}

	// ------------------------------------------------------------------------------------------

	private void scheduleConfigRefresh(long delaySeconds)
	{
		if (executor == null)
		{
			return;
		}
		executor.schedule(this::refreshConfig, Math.max(0L, delaySeconds), TimeUnit.SECONDS);
	}

	private void refreshConfig()
	{
		if (!api.isConfigured())
		{
			// The consent gate: no token means no request, ever.
			setConnection(PanelState.Connection.NOT_CONFIGURED, null);
			scheduleConfigRefresh(CONFIG_RETRY_SECONDS);
			return;
		}

		if (eventState == null)
		{
			setConnection(PanelState.Connection.CONNECTING, null);
		}

		final Instant sentAt = Instant.now();
		api.fetchConfig(sentAt, new ApiCallback<ApiDtos.ConfigResponse>()
		{
			@Override
			public void onSuccess(ApiDtos.ConfigResponse result)
			{
				final Instant receivedAt = Instant.now();
				executor.execute(() -> applyConfig(result, sentAt, receivedAt));
			}

			@Override
			public void onFailure(ApiException error)
			{
				executor.execute(() -> onConfigFailed(error));
			}
		});
	}

	private void applyConfig(ApiDtos.ConfigResponse response, Instant sentAt, Instant receivedAt)
	{
		if (response == null || !response.ok || response.event == null)
		{
			setConnection(PanelState.Connection.NO_EVENT, "No event is running right now");
			scheduleConfigRefresh(CONFIG_RETRY_SECONDS);
			return;
		}

		if (response.serverTime != null)
		{
			try
			{
				serverClock.sync(Instant.parse(response.serverTime), sentAt, receivedAt);
			}
			catch (java.time.format.DateTimeParseException e)
			{
				log.debug("Bingo BrazilChat: unreadable serverTime {}", response.serverTime);
			}
		}

		List<CatalogItem> items = new ArrayList<>();
		if (response.items != null)
		{
			for (ApiDtos.ItemDto dto : response.items)
			{
				items.add(new CatalogItem(dto.id, dto.name, dto.raid, dto.points));
			}
		}

		List<String> ignored = response.ignored != null
			? response.ignored
			: bakedAliases.getIgnored();

		DropCatalog catalog = DropCatalog.build(items, response.aliases,
			bakedAliases.getAliases(), ignored);

		eventState = EventState.from(response, catalog);

		if (eventState.getWindow().getEnd() != null)
		{
			queue.setEventEnd(eventState.getWindow().getEnd().toEpochMilli());
		}

		setConnection(PanelState.Connection.ONLINE,
			serverClock.isSkewed()
				? "Your PC clock is out by " + (serverClock.getOffsetMillis() / 1000) + "s"
				: null);

		log.debug("Bingo BrazilChat: catalog has {} names, roster has {} players",
			catalog.size(), eventState.getRoster().size());

		long poll = response.policy == null ? 300L : response.policy.configPollSeconds;
		scheduleConfigRefresh(Math.max(30L, poll));
	}

	private void onConfigFailed(ApiException error)
	{
		if (error.isAuthFailure())
		{
			setConnection(PanelState.Connection.UNAUTHORIZED,
				"Check your event token in the plugin settings");
		}
		else if (error.getHttpStatus() == 503)
		{
			setConnection(PanelState.Connection.NO_EVENT, "No event is running right now");
		}
		else
		{
			setConnection(PanelState.Connection.OFFLINE, "Cannot reach the site");
		}
		scheduleConfigRefresh(CONFIG_RETRY_SECONDS);
	}

	private void scheduleLeaderboardRefresh()
	{
		if (executor == null)
		{
			return;
		}
		executor.scheduleWithFixedDelay(this::refreshLeaderboard, 5L, 60L, TimeUnit.SECONDS);
	}

	private void refreshLeaderboard()
	{
		EventState state = eventState;
		if (!api.isConfigured() || state == null)
		{
			return;
		}

		api.fetchLeaderboard(state.getWindow().getEventId(), leaderboardEtag,
			new BingoApiClient.LeaderboardCallback()
			{
				@Override
				public void onSuccess(ApiDtos.LeaderboardResponse result, @Nullable String etag)
				{
					executor.execute(() ->
					{
						leaderboardEtag = etag;
						teams = result.teams == null ? Collections.emptyList() : result.teams;
						pushPanelState();
					});
				}

				@Override
				public void onUnchanged()
				{
					// Nothing moved since our last fetch; the panel is already correct.
				}

				@Override
				public void onFailure(ApiException error)
				{
					log.debug("Bingo BrazilChat: leaderboard fetch failed", error);
				}
			});
	}

	private void setConnection(PanelState.Connection next, @Nullable String detail)
	{
		connection = next;
		connectionDetail = detail;
		pushPanelState();
	}

	private void pushPanelState()
	{
		BingoPanel current = panel;
		if (current == null)
		{
			return;
		}
		EventState state = eventState;
		current.setState(new PanelState(
			connection,
			connectionDetail,
			state == null ? null : state.getWindow(),
			teams,
			queueSnapshot,
			serverClock.isSkewed()));
	}

	/**
	 * Local-only confirmation that a drop reached the site, printed on the client thread.
	 *
	 * <p>Only fires for a submission this client actually recorded, never for one that came back as
	 * a duplicate -- otherwise every member of the clan would print the same line for one drop.
	 */
	private void announceRecorded(QueuedSubmission submission)
	{
		if (!config.announceInChat())
		{
			return;
		}

		String item = submission.getItemDisplayName() == null
			? submission.getItemNameRaw()
			: submission.getItemDisplayName();
		String message = "[Bingo BrazilChat] Recorded " + item
			+ " for " + submission.getRsn()
			+ (submission.getPoints() > 0 ? " (" + submission.getPoints() + " pts)" : "");

		clientThread.invokeLater(() ->
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
			return true;
		});
	}
}

package com.bingobrazilchat.api;

/**
 * Result of an API call. Both methods are invoked on an OkHttp dispatcher thread, so an
 * implementation that touches queue state must hop back onto the plugin executor first.
 */
public interface ApiCallback<T>
{
	void onSuccess(T result);

	void onFailure(ApiException error);
}

package com.bingobrazilchat.api;

import java.util.List;
import java.util.Map;

/**
 * Wire shapes for {@code /api/plugin/*}. Plain fields, deserialised by the injected Gson.
 *
 * <p>Field names match the JSON exactly, so there are no {@code @SerializedName} annotations to
 * fall out of step with the server.
 */
public final class ApiDtos
{
	private ApiDtos()
	{
	}

	public static class ConfigResponse
	{
		public boolean ok;
		public String error;
		public String serverTime;
		public EventDto event;
		public List<ItemDto> items;
		/** Normalised in-game item name -&gt; drop_item_id. Authoritative over the baked-in table. */
		public Map<String, String> aliases;
		public List<String> ignored;
		public List<String> roster;
		public PolicyDto policy;
	}

	public static class EventDto
	{
		public String id;
		public String name;
		/** ISO-8601 UTC, or null for an unbounded event. */
		public String startDate;
		public String endDate;
	}

	public static class ItemDto
	{
		public String id;
		public String name;
		public int points;
		public String raid;
	}

	public static class PolicyDto
	{
		public long observerDelayMs = 20_000L;
		public long observerJitterMs = 15_000L;
		public long herdWindowSeconds = 120L;
		public long maxProofBytes = 3_145_728L;
		public long configPollSeconds = 300L;
		public long leaderboardPollSeconds = 60L;
	}

	/** Phase 1: what we tell the server happened. Carries no screenshot. */
	public static class ClaimRequest
	{
		public String eventId;
		public String rsn;
		public String dropItemId;
		public String itemNameRaw;
		public String broadcastType;
		public String rawMessage;
		public String occurredAt;
		public boolean observer;
		public String reporterRsn;
		public String dedupeKey;
		public boolean hasProof;
		public String clientVersion;
	}

	public static class ClaimResponse
	{
		public boolean ok;
		public String error;
		/** {@code created} | {@code duplicate} | {@code rejected}. */
		public String status;
		public String reason;
		public String submissionId;
		public boolean proofUploadRequired;
		public String proofUploadToken;
		public String itemName;
		public int points;
		public String playerRsn;

		public boolean isCreated()
		{
			return "created".equals(status);
		}

		public boolean isDuplicate()
		{
			return "duplicate".equals(status);
		}

		public boolean isRejected()
		{
			return "rejected".equals(status);
		}
	}

	public static class LeaderboardResponse
	{
		public boolean ok;
		public String generatedAt;
		public EventDto event;
		public List<TeamRow> teams;
		public List<PlayerRow> players;
	}

	public static class TeamRow
	{
		public int rank;
		public String teamId;
		public String name;
		public String color;
		public int points;
		public int uniqueItems;
		public int memberCount;
	}

	public static class PlayerRow
	{
		public int rank;
		public String rsn;
		public String teamName;
		public int points;
		public int uniqueItems;
	}
}

package com.bingobrazilchat.api;

import lombok.Getter;

/**
 * A failed API call, carrying the one thing the queue actually needs to decide: whether trying
 * again could ever help.
 *
 * <p>Getting this classification wrong in the retryable direction is expensive -- a bad shared
 * token would otherwise have every client in the clan retrying a 401 against Vercel forever.
 */
@Getter
public class ApiException extends Exception
{
	/** HTTP status, or -1 for a transport-level failure (timeout, DNS, connection reset). */
	private final int httpStatus;

	private final boolean retryable;

	/** Seconds the server asked us to wait, from Retry-After. Zero when it did not say. */
	private final long retryAfterSeconds;

	public ApiException(String message, int httpStatus, boolean retryable, long retryAfterSeconds)
	{
		super(message);
		this.httpStatus = httpStatus;
		this.retryable = retryable;
		this.retryAfterSeconds = retryAfterSeconds;
	}

	public static ApiException transport(String message)
	{
		// No response at all: the network or the server is down, and both recover on their own.
		return new ApiException(message, -1, true, 0L);
	}

	public static ApiException fromStatus(int status, String body, long retryAfterSeconds)
	{
		return new ApiException("HTTP " + status + (body == null || body.isEmpty() ? "" : ": " + body),
			status, isRetryableStatus(status), retryAfterSeconds);
	}

	private static boolean isRetryableStatus(int status)
	{
		// 429 and 5xx are the server telling us to come back. Everything else in the 4xx range is
		// a statement about the request itself, which will not improve by repeating it.
		return status == 429 || status >= 500;
	}

	/** True when the failure means the token is wrong, so the panel can say so plainly. */
	public boolean isAuthFailure()
	{
		return httpStatus == 401 || httpStatus == 403;
	}
}

package com.bingobrazilchat.api;

import com.bingobrazilchat.BingoBrazilChatConfig;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.time.Instant;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Every HTTP call this plugin makes.
 *
 * <p>Two RuneLite-specific constraints shape this class:
 *
 * <ul>
 *   <li>The injected {@link OkHttpClient} carries an interceptor that <em>throws</em> on a blocking
 *       call made from the client thread or the EDT. So every call here uses {@code enqueue}, never
 *       {@code execute} -- with enqueue the interceptor runs on a dispatcher thread and passes.</li>
 *   <li>The shared instance must not be mutated, so per-call timeouts go through
 *       {@code newBuilder()} once, at construction.</li>
 * </ul>
 *
 * <p>The plugin is inert until a token is configured: {@link #isConfigured()} gates every call, so
 * an unconfigured install genuinely never touches the network.
 */
@Slf4j
@Singleton
public class BingoApiClient
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.get("image/png");
	private static final String CLIENT_VERSION = "1.0.0";

	/**
	 * The only host this plugin ever contacts.
	 *
	 * <p>Deliberately a constant rather than a config field: a user-editable address would let a
	 * player be talked into pointing their RSN and screenshots at somewhere else, and it makes the
	 * plugin's network behaviour impossible to state precisely. To test against a local server,
	 * change this line and rebuild.
	 */
	private static final String BASE_URL = "https://brazilchat.vercel.app";

	private final OkHttpClient http;
	private final Gson gson;
	private final BingoBrazilChatConfig config;

	@Inject
	public BingoApiClient(OkHttpClient okHttpClient, Gson gson, BingoBrazilChatConfig config)
	{
		this.http = okHttpClient.newBuilder()
			.callTimeout(30, TimeUnit.SECONDS)
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(20, TimeUnit.SECONDS)
			.build();
		this.gson = gson;
		this.config = config;
	}

	public boolean isConfigured()
	{
		return !token().isEmpty() && baseUrl() != null;
	}

	/**
	 * Fetches the event window, catalog, aliases and roster.
	 *
	 * @param sentAt when the request left, so the caller can measure clock skew against the
	 *               {@code serverTime} in the reply
	 */
	public void fetchConfig(Instant sentAt, ApiCallback<ApiDtos.ConfigResponse> callback)
	{
		HttpUrl url = path("config");
		if (url == null)
		{
			callback.onFailure(ApiException.transport("Invalid site address"));
			return;
		}

		enqueue(authed(new Request.Builder().url(url).get()).build(),
			ApiDtos.ConfigResponse.class, callback);
		log.debug("Bingo BrazilChat: config requested at {}", sentAt);
	}

	/** Phase 1 of a submission: tell the server the drop happened. No image is sent here. */
	public void claimDrop(ApiDtos.ClaimRequest claim, ApiCallback<ApiDtos.ClaimResponse> callback)
	{
		HttpUrl url = path("drops");
		if (url == null)
		{
			callback.onFailure(ApiException.transport("Invalid site address"));
			return;
		}

		claim.clientVersion = CLIENT_VERSION;
		RequestBody body = RequestBody.create(JSON, gson.toJson(claim));

		Request request = authed(new Request.Builder().url(url).post(body))
			// Lets a proxy or a future server-side cache collapse a retry without our help.
			.header("Idempotency-Key", claim.dedupeKey)
			.build();

		enqueue(request, ApiDtos.ClaimResponse.class, callback);
	}

	/**
	 * Phase 2: attach the screenshot. Only the client whose claim returned {@code created} holds a
	 * valid proof token, so only it gets here -- which is the whole reason the screenshot is a
	 * separate request rather than part of the claim.
	 */
	public void uploadProof(String submissionId, String proofToken, byte[] png,
		ApiCallback<Void> callback)
	{
		HttpUrl url = path("drops", submissionId, "proof");
		if (url == null)
		{
			callback.onFailure(ApiException.transport("Invalid site address"));
			return;
		}

		RequestBody form = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("file", submissionId + ".png", RequestBody.create(PNG, png))
			.build();

		Request request = authed(new Request.Builder().url(url).post(form))
			.header("X-Proof-Token", proofToken)
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.onFailure(ApiException.transport(e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					// 409 means the proof is already attached. That is the outcome we wanted, so
					// treat it as success rather than retrying forever against a settled row.
					if (r.isSuccessful() || r.code() == 409)
					{
						callback.onSuccess(null);
						return;
					}
					callback.onFailure(ApiException.fromStatus(r.code(), bodySnippet(r.body()),
						retryAfter(r)));
				}
			}
		});
	}

	/** @param etag the last ETag we saw, so an unchanged board costs a 304 instead of a payload */
	public void fetchLeaderboard(@Nullable String eventId, @Nullable String etag,
		LeaderboardCallback callback)
	{
		HttpUrl base = path("leaderboard");
		if (base == null)
		{
			callback.onFailure(ApiException.transport("Invalid site address"));
			return;
		}

		HttpUrl url = eventId == null ? base
			: base.newBuilder().addQueryParameter("eventId", eventId).build();

		Request.Builder builder = authed(new Request.Builder().url(url).get());
		if (etag != null && !etag.isEmpty())
		{
			builder.header("If-None-Match", etag);
		}

		http.newCall(builder.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.onFailure(ApiException.transport(e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.code() == 304)
					{
						callback.onUnchanged();
						return;
					}
					if (!r.isSuccessful())
					{
						callback.onFailure(ApiException.fromStatus(r.code(),
							bodySnippet(r.body()), retryAfter(r)));
						return;
					}
					ApiDtos.LeaderboardResponse parsed =
						parse(r.body(), ApiDtos.LeaderboardResponse.class);
					if (parsed == null)
					{
						callback.onFailure(ApiException.transport("Unreadable leaderboard"));
						return;
					}
					callback.onSuccess(parsed, r.header("ETag"));
				}
			}
		});
	}

	public interface LeaderboardCallback
	{
		void onSuccess(ApiDtos.LeaderboardResponse result, @Nullable String etag);

		/** The board has not changed since the ETag we sent. */
		void onUnchanged();

		void onFailure(ApiException error);
	}

	// ------------------------------------------------------------------------------------------

	private <T> void enqueue(Request request, Class<T> type, ApiCallback<T> callback)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.onFailure(ApiException.transport(e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						callback.onFailure(ApiException.fromStatus(r.code(),
							bodySnippet(r.body()), retryAfter(r)));
						return;
					}
					T parsed = parse(r.body(), type);
					if (parsed == null)
					{
						callback.onFailure(ApiException.transport("Unreadable response"));
						return;
					}
					callback.onSuccess(parsed);
				}
			}
		});
	}

	@Nullable
	private <T> T parse(@Nullable ResponseBody body, Class<T> type)
	{
		if (body == null)
		{
			return null;
		}
		try
		{
			return gson.fromJson(body.charStream(), type);
		}
		catch (JsonSyntaxException e)
		{
			log.debug("Bingo BrazilChat: unparseable response", e);
			return null;
		}
	}

	private Request.Builder authed(Request.Builder builder)
	{
		return builder
			.header("Authorization", "Bearer " + token())
			.header("Accept", "application/json")
			.header("X-Plugin-Version", CLIENT_VERSION)
			.header("User-Agent", "BingoBrazilChat/" + CLIENT_VERSION);
	}

	@Nullable
	private HttpUrl path(String... segments)
	{
		HttpUrl base = baseUrl();
		if (base == null)
		{
			return null;
		}
		HttpUrl.Builder builder = base.newBuilder().addPathSegment("api").addPathSegment("plugin");
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	@Nullable
	private HttpUrl baseUrl()
	{
		return HttpUrl.parse(BASE_URL);
	}

	private String token()
	{
		String raw = config.sharedToken();
		return raw == null ? "" : raw.trim();
	}

	private static long retryAfter(Response response)
	{
		String header = response.header("Retry-After");
		if (header == null)
		{
			return 0L;
		}
		try
		{
			return Math.max(0L, Long.parseLong(header.trim()));
		}
		catch (NumberFormatException e)
		{
			return 0L;
		}
	}

	/** Body text for the log, capped so a stray HTML error page cannot flood the client log. */
	private static String bodySnippet(@Nullable ResponseBody body)
	{
		if (body == null)
		{
			return "";
		}
		try
		{
			String text = body.string();
			return text.length() > 300 ? text.substring(0, 300) : text;
		}
		catch (IOException e)
		{
			return "";
		}
	}
}

package com.bingobrazilchat.capture;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;

/**
 * Turns a captured frame into PNG bytes small enough to upload.
 *
 * <p>Everything here is slow enough (tens to low hundreds of milliseconds) that it must never run
 * on the client thread -- it would show up as a visible stutter at the exact moment the player got
 * their drop.
 */
@Slf4j
public final class ImageEncoder
{
	private ImageEncoder()
	{
	}

	/**
	 * @param scalePercent 25-100; downscaling is what keeps the upload comfortably under both our
	 *                     own cap and Vercel's 4.5 MB request-body limit
	 * @return PNG bytes, or null if the frame could not be encoded
	 */
	@Nullable
	public static byte[] toPng(Image source, int scalePercent, long maxBytes)
	{
		BufferedImage image = toBuffered(source);
		if (image == null)
		{
			return null;
		}

		int clamped = Math.max(25, Math.min(100, scalePercent));
		if (clamped < 100)
		{
			image = scale(image, clamped / 100.0);
		}

		byte[] encoded = encode(image);
		if (encoded == null)
		{
			return null;
		}

		// One halving pass rather than a loop: if a 50%-of-requested-size render still will not
		// fit, the frame is pathological and sending no image beats sending a useless one.
		if (encoded.length > maxBytes)
		{
			log.debug("Bingo BrazilChat: screenshot {} bytes exceeds {}, halving", encoded.length, maxBytes);
			byte[] smaller = encode(scale(image, 0.5));
			return smaller != null && smaller.length <= maxBytes ? smaller : null;
		}

		return encoded;
	}

	@Nullable
	private static BufferedImage toBuffered(Image source)
	{
		if (source == null)
		{
			return null;
		}
		if (source instanceof BufferedImage)
		{
			return (BufferedImage) source;
		}

		int width = source.getWidth(null);
		int height = source.getHeight(null);
		if (width <= 0 || height <= 0)
		{
			return null;
		}

		BufferedImage copy = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = copy.createGraphics();
		try
		{
			g.drawImage(source, 0, 0, null);
		}
		finally
		{
			g.dispose();
		}
		return copy;
	}

	private static BufferedImage scale(BufferedImage source, double factor)
	{
		int width = Math.max(1, (int) Math.round(source.getWidth() * factor));
		int height = Math.max(1, (int) Math.round(source.getHeight() * factor));

		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = scaled.createGraphics();
		try
		{
			// Bilinear, not nearest-neighbour: the proof has to stay legible enough to read the
			// broadcast line in the chatbox.
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(source, 0, 0, width, height, null);
		}
		finally
		{
			g.dispose();
		}
		return scaled;
	}

	@Nullable
	private static byte[] encode(BufferedImage image)
	{
		try
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			// ImageIO.write returns false rather than throwing when no writer is available.
			if (!ImageIO.write(image, "png", out))
			{
				log.debug("Bingo BrazilChat: no PNG writer available");
				return null;
			}
			return out.toByteArray();
		}
		catch (IOException e)
		{
			log.debug("Bingo BrazilChat: failed to encode screenshot", e);
			return null;
		}
	}
}

package com.bingobrazilchat.capture;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;

/**
 * Captures one client frame and hands back PNG bytes.
 *
 * <p>Two hazards this exists to handle:
 *
 * <ol>
 *   <li><b>The frame arrives on the client thread.</b> {@code requestNextFrameListener} fires its
 *       consumer at end-of-frame on the client thread, so the consumer here does nothing except
 *       hand the image to our own executor. This mirrors RuneLite's own {@code ImageCapture}.</li>
 *   <li><b>The callback can silently never fire.</b> Inside {@code DrawManager.processDrawComplete},
 *       if the image supplier returns null -- which happens with some renderer states, or when the
 *       client is not drawing at all -- RuneLite clears the pending listeners without notifying
 *       them. Without the timeout below, a submission would sit waiting for proof forever.</li>
 * </ol>
 */
@Slf4j
@Singleton
public class ScreenshotService
{
	/** Generous: a frame normally lands in well under 100ms, so this only fires when none will. */
	private static final long FRAME_TIMEOUT_MS = 5_000L;

	private final DrawManager drawManager;

	@Inject
	public ScreenshotService(DrawManager drawManager)
	{
		this.drawManager = drawManager;
	}

	/**
	 * Requests the next rendered frame.
	 *
	 * <p>Safe to call from the client thread: {@code requestNextFrameListener} is backed by a
	 * concurrent queue.
	 *
	 * @param onResult receives the PNG bytes, or null if no frame arrived in time or it could not
	 *                 be encoded. Always invoked exactly once, on {@code executor}.
	 */
	public void capture(ScheduledExecutorService executor, int scalePercent, long maxBytes,
		Consumer<byte[]> onResult)
	{
		final AtomicBoolean delivered = new AtomicBoolean(false);

		drawManager.requestNextFrameListener(image ->
		{
			// Still the client thread here. Encoding is far too slow to do inline -- it would
			// stutter the game at the exact moment the player got their drop.
			executor.execute(() ->
			{
				if (!delivered.compareAndSet(false, true))
				{
					return;
				}
				byte[] png = null;
				try
				{
					png = ImageEncoder.toPng(image, scalePercent, maxBytes);
				}
				catch (RuntimeException e)
				{
					log.debug("Bingo BrazilChat: screenshot encode failed", e);
				}
				onResult.accept(png);
			});
		});

		executor.schedule(() ->
		{
			if (delivered.compareAndSet(false, true))
			{
				log.debug("Bingo BrazilChat: no frame within {}ms, submitting without proof",
					FRAME_TIMEOUT_MS);
				onResult.accept(null);
			}
		}, FRAME_TIMEOUT_MS, TimeUnit.MILLISECONDS);
	}

}

package com.bingobrazilchat.catalog;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Loads the shipped {@code aliases.json} fallback.
 *
 * <p>The {@link Gson} instance is passed in rather than constructed. The Plugin Hub packager fails
 * the build outright if a plugin builds its own Gson under {@code src/main} -- RuneLite provides an
 * injectable one, and that is the only instance a plugin should use.
 */
public final class AliasResource
{
	private static final String RESOURCE = "/com/bingobrazilchat/aliases.json";

	private AliasResource()
	{
	}

	public static Loaded load(Gson gson) throws IOException
	{
		try (InputStream in = AliasResource.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing bundled resource " + RESOURCE);
			}
			Type type = new TypeToken<RawFile>()
			{
			}.getType();
			RawFile raw = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
			if (raw == null)
			{
				throw new IOException("Unparseable " + RESOURCE);
			}

			Map<String, DropCatalog.AliasTarget> aliases = new HashMap<>();
			if (raw.aliases != null)
			{
				for (Map.Entry<String, RawTarget> e : raw.aliases.entrySet())
				{
					RawTarget t = e.getValue();
					if (t != null && t.name != null && t.raid != null)
					{
						aliases.put(e.getKey(), new DropCatalog.AliasTarget(t.name, t.raid));
					}
				}
			}

			List<String> ignored = raw.ignored == null ? new ArrayList<>() : raw.ignored;
			return new Loaded(Collections.unmodifiableMap(aliases),
				Collections.unmodifiableList(ignored));
		}
	}

	@Value
	public static class Loaded
	{
		Map<String, DropCatalog.AliasTarget> aliases;
		List<String> ignored;
	}

	private static final class RawFile
	{
		Map<String, RawTarget> aliases;
		List<String> ignored;
	}

	private static final class RawTarget
	{
		String name;
		String raid;
	}
}

package com.bingobrazilchat.catalog;

import lombok.Value;

/**
 * One scoreable item, as the website defines it.
 *
 * <p>{@code dropItemId} is the identity that matters. Resolving to a UUID rather than a name is
 * required because "Kit/Dust" exists twice in {@code drop_items} -- once under CoX and once under
 * ToB -- so a name alone is ambiguous and only the alias entry knows which raid it came from.
 */
@Value
public class CatalogItem
{
	/** {@code drop_items.id} on the server. */
	String dropItemId;

	/** The catalog's own display name, e.g. "Kodai Wand". */
	String catalogName;

	/** {@code cox} | {@code tob} | {@code toa}. */
	String raid;

	int points;
}

package com.bingobrazilchat.catalog;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Resolves an in-game item name to the catalog entry it scores as.
 *
 * <p>Three layers, in precedence order:
 * <ol>
 *   <li>the server's alias map (normalized in-game name -&gt; {@code drop_item_id}), which is
 *       authoritative and can be corrected with a Vercel deploy rather than a plugin release;</li>
 *   <li>a direct match on the catalog's own name, which covers the majority of items;</li>
 *   <li>the baked-in alias table, a safety net for the handful of names where the in-game item and
 *       the catalog entry genuinely differ (see {@code aliases.json}).</li>
 * </ol>
 *
 * <p>Anything unresolved is either a known non-scoring raid drop (see {@link #isKnownIgnored}) or a
 * genuine surprise worth logging.
 */
public final class DropCatalog
{
	private final Map<String, CatalogItem> byName;
	private final Set<String> ignored;

	private DropCatalog(Map<String, CatalogItem> byName, Set<String> ignored)
	{
		this.byName = Collections.unmodifiableMap(byName);
		this.ignored = Collections.unmodifiableSet(ignored);
	}

	/** An empty catalog: what the plugin runs on before it has ever reached the server. */
	public static DropCatalog empty()
	{
		return new DropCatalog(new HashMap<>(), new HashSet<>());
	}

	/**
	 * Builds the live catalog.
	 *
	 * @param items        the catalog rows from {@code /api/plugin/config}
	 * @param serverAlias  normalized in-game name -&gt; {@code drop_item_id}, from the same response
	 * @param bakedAlias   the shipped fallback table, normalized in-game name -&gt; (name, raid)
	 * @param ignoredNames normalized names that broadcast as raid loot but deliberately score zero
	 */
	public static DropCatalog build(
		Iterable<CatalogItem> items,
		Map<String, String> serverAlias,
		Map<String, AliasTarget> bakedAlias,
		Iterable<String> ignoredNames)
	{
		Map<String, CatalogItem> byId = new HashMap<>();
		Map<String, CatalogItem> resolved = new HashMap<>();

		for (CatalogItem item : items)
		{
			byId.put(item.getDropItemId(), item);
			// Layer 2: the catalog's own name. Note this intentionally lets a later raid overwrite
			// an earlier one for an ambiguous name like "Kit/Dust" -- such names are never resolved
			// this way in practice, because every real in-game name for them goes through an alias.
			resolved.put(ItemNameNormalizer.normalize(item.getCatalogName()), item);
		}

		// Layer 3 first, so layer 1 can overwrite it below.
		if (bakedAlias != null)
		{
			for (Map.Entry<String, AliasTarget> e : bakedAlias.entrySet())
			{
				CatalogItem target = findByNameAndRaid(items, e.getValue());
				if (target != null)
				{
					resolved.put(ItemNameNormalizer.normalize(e.getKey()), target);
				}
			}
		}

		// Layer 1: the server always wins.
		if (serverAlias != null)
		{
			for (Map.Entry<String, String> e : serverAlias.entrySet())
			{
				CatalogItem target = byId.get(e.getValue());
				if (target != null)
				{
					resolved.put(ItemNameNormalizer.normalize(e.getKey()), target);
				}
			}
		}

		Set<String> ignoredSet = new HashSet<>();
		if (ignoredNames != null)
		{
			for (String n : ignoredNames)
			{
				ignoredSet.add(ItemNameNormalizer.normalize(n));
			}
		}

		return new DropCatalog(resolved, ignoredSet);
	}

	public Optional<CatalogItem> lookup(String rawItemName)
	{
		return Optional.ofNullable(byName.get(ItemNameNormalizer.normalize(rawItemName)));
	}

	/**
	 * True for raid loot we know about and have decided not to score -- pets, dark relics, the ToA
	 * upgrade items. Distinguishing these from genuine surprises keeps the debug log signal-heavy.
	 */
	public boolean isKnownIgnored(String rawItemName)
	{
		return ignored.contains(ItemNameNormalizer.normalize(rawItemName));
	}

	public boolean isEmpty()
	{
		return byName.isEmpty();
	}

	public int size()
	{
		return byName.size();
	}

	private static CatalogItem findByNameAndRaid(Iterable<CatalogItem> items, AliasTarget target)
	{
		String wantName = ItemNameNormalizer.normalize(target.getName());
		for (CatalogItem item : items)
		{
			if (ItemNameNormalizer.normalize(item.getCatalogName()).equals(wantName)
				&& item.getRaid().equalsIgnoreCase(target.getRaid()))
			{
				return item;
			}
		}
		return null;
	}

	/**
	 * A baked-in alias points at a (catalog name, raid) pair rather than an id, because the shipped
	 * resource cannot know the server-generated UUIDs. The raid half is what disambiguates the two
	 * "Kit/Dust" rows.
	 */
	@lombok.Value
	public static class AliasTarget
	{
		String name;
		String raid;
	}
}

package com.bingobrazilchat.catalog;

import com.bingobrazilchat.util.Sanitizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * Produces the lookup key for an item name.
 *
 * <p>The catalog on the website is Title Case ("Twisted Bow"); the game broadcasts sentence case
 * ("Twisted bow"). Both sides go through this, so the two meet in the middle.
 */
public final class ItemNameNormalizer
{
	/**
	 * Suffixes stripped before lookup. These denote a charge state of the item the raid actually
	 * dropped -- "Scythe of Vitur (uncharged)" is the drop, "Scythe of Vitur" is the catalog entry.
	 *
	 * <p>Deliberately NOT stripped: {@code (or)}, {@code (f)}, {@code (t)}, {@code (b)}. Those mark
	 * upgrades the player <em>built</em> ("Masori body (f)", "Osmumten's fang (or)") and never drop
	 * from a raid. Accepting them would score points for a cosmetic recolour.
	 */
	private static final List<String> CHARGE_SUFFIXES =
		Arrays.asList(" (uncharged)", " (broken)", " (empty)");

	private ItemNameNormalizer()
	{
	}

	public static String normalize(String rawItemName)
	{
		if (rawItemName == null)
		{
			return "";
		}

		// Locale.ROOT is mandatory. RuneLite's Text.standardize() lowercases with the default
		// locale, which on a Turkish-locale machine turns "TWISTED BOW" into "twisted bow" with a
		// dotless i -- and every catalog lookup silently misses.
		String s = Sanitizer.clean(rawItemName).toLowerCase(Locale.ROOT).trim();

		for (String suffix : CHARGE_SUFFIXES)
		{
			if (s.endsWith(suffix))
			{
				// One suffix only: a name never carries two charge states.
				return s.substring(0, s.length() - suffix.length()).trim();
			}
		}

		return s;
	}
}

package com.bingobrazilchat.chat;

/**
 * Which broadcast template a line matched. Sent to the server as {@code broadcastType} so an admin
 * reviewing Drop History can tell a high-confidence raid purple from a value-drop line that merely
 * happened to name a raid item.
 */
public enum BroadcastKind
{
	/**
	 * "{@code <RSN> received special loot from a raid: <Item>.}" -- the authoritative signal. Only
	 * fires for genuine raid uniques, so a match here is as close to proof as chat gets.
	 */
	RAID_SPECIAL_LOOT("raid_special_loot"),

	/**
	 * "{@code <RSN> received a drop: <Item> (<value> coins) from <Source>.}" -- the value-threshold
	 * broadcast. Lower confidence: a raid unique can appear here via a wilderness loot key or a PK,
	 * so these are flagged for audit rather than trusted outright.
	 */
	VALUE_DROP("value_drop");

	private final String wireName;

	BroadcastKind(String wireName)
	{
		this.wireName = wireName;
	}

	public String getWireName()
	{
		return wireName;
	}
}

package com.bingobrazilchat.chat;

import com.bingobrazilchat.util.RsnUtil;
import com.bingobrazilchat.util.Sanitizer;
import java.util.Optional;
import java.util.regex.Matcher;

/**
 * Turns a raw clan chat line into a {@link ParsedBroadcast}, or nothing.
 *
 * <p>Pure: no RuneLite types, no state, no I/O. That is deliberate -- broadcast wording is the part
 * of this plugin most likely to be wrong, and keeping the parser dependency-free means it can be
 * exercised against real strings in a plain unit test instead of a running game client.
 */
public final class BroadcastParser
{
	private BroadcastParser()
	{
	}

	public static Optional<ParsedBroadcast> parse(String rawMessage)
	{
		final String line = Sanitizer.clean(rawMessage);
		if (line.isEmpty())
		{
			return Optional.empty();
		}

		Matcher raid = BroadcastPatterns.RAID_SPECIAL_LOOT.matcher(line);
		if (raid.matches())
		{
			return build(BroadcastKind.RAID_SPECIAL_LOOT, raid.group("rsn"), raid.group("item"),
				raid.group("value"), null, null, line);
		}

		Matcher drop = BroadcastPatterns.VALUE_DROP.matcher(line);
		if (drop.matches())
		{
			return build(BroadcastKind.VALUE_DROP, drop.group("rsn"), drop.group("item"),
				drop.group("value"), drop.group("qty"), drop.group("source"), line);
		}

		return Optional.empty();
	}

	/**
	 * True when a line looks like a drop announcement we failed to parse. Used only to decide what
	 * to write to the debug log, so that a wording mismatch shows up as a log line during testing
	 * rather than as a silent no-op during the event.
	 */
	public static boolean looksLikeUnparsedDrop(String rawMessage)
	{
		String line = Sanitizer.clean(rawMessage);
		return line.contains(BroadcastPatterns.RECEIVED_HINT) && !parse(rawMessage).isPresent();
	}

	private static Optional<ParsedBroadcast> build(BroadcastKind kind, String rsn, String item,
		String value, String qty, String source, String line)
	{
		String cleanRsn = rsn == null ? "" : rsn.trim();
		String cleanItem = item == null ? "" : item.trim();

		// A name the server would reject anyway is dropped here, before it can reach the queue.
		// This also filters out lines that structurally matched but captured nonsense, which is the
		// usual failure mode of a lazy leading group.
		if (cleanItem.isEmpty() || !RsnUtil.isValid(cleanRsn))
		{
			return Optional.empty();
		}

		return Optional.of(new ParsedBroadcast(
			kind, cleanRsn, cleanItem, parseNumber(value, -1L), (int) parseNumber(qty, 1L),
			source == null ? null : source.trim(), line));
	}

	private static long parseNumber(String withCommas, long fallback)
	{
		if (withCommas == null || withCommas.isEmpty())
		{
			return fallback;
		}
		try
		{
			return Long.parseLong(withCommas.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

package com.bingobrazilchat.chat;

import java.util.regex.Pattern;

/**
 * The broadcast templates, kept in one place so a wording change is a single-file edit.
 *
 * <p>RuneLite itself does not parse clan drop broadcasts -- the client source has no pattern for
 * "special loot" or "received a drop" anywhere (its {@code ScreenshotPlugin} only handles the local
 * {@code Valuable drop:} / {@code Untradeable drop:} game messages). So these are ours, written
 * from observed broadcast shapes.
 *
 * <p>Both patterns run <em>after</em> {@link com.bingobrazilchat.util.Sanitizer#clean(String)}.
 */
public final class BroadcastPatterns
{
	/**
	 * "{@code Zezinho received special loot from a raid: Kodai insignia.}"
	 *
	 * <p>The trailing full stop is optional -- both forms occur in the wild. The optional trailing
	 * {@code (1,234,567)} group is defensive: sources disagree on whether this line carries a GE
	 * value. It is safe to include because it accepts only digits and commas, so it can never eat a
	 * legitimate {@code (uncharged)} suffix off the item name.
	 */
	public static final Pattern RAID_SPECIAL_LOOT = Pattern.compile(
		"^(?<rsn>.+?) received special loot from a raid: (?<item>.+?)"
			+ "(?: \\((?<value>[\\d,]+)\\))?\\.?$");

	/**
	 * "{@code Zezinho received a drop: Voidwaker blade (39,648,370 coins) from Vet'ion.}"
	 *
	 * <p>The {@code from <Source>} clause is not optional to <em>handle</em>: without it the lazy
	 * item group swallows "{@code (39,648,370 coins) from Vet'ion}" whole and the catalog lookup
	 * fails silently.
	 */
	public static final Pattern VALUE_DROP = Pattern.compile(
		"^(?<rsn>.+?) received a drop: "
			+ "(?:(?<qty>[\\d,]+) x )?"
			+ "(?<item>.+?)"
			+ "(?: \\((?<value>[\\d,]+) coins\\))?"
			+ "(?: from (?<source>.+?))?\\.?$");

	/**
	 * Cheap pre-filter for the debug log: any clan line mentioning a receipt that matched neither
	 * pattern above is worth surfacing, because it is probably a template we got wrong.
	 */
	public static final String RECEIVED_HINT = " received ";

	private BroadcastPatterns()
	{
	}
}

package com.bingobrazilchat.chat;

import com.bingobrazilchat.BingoBrazilChatConfig;
import com.bingobrazilchat.event.EventState;
import com.bingobrazilchat.submit.DropPipeline;
import java.util.Optional;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

/**
 * Watches clan chat for drop broadcasts.
 *
 * <p>Registered manually on the event bus (see the plugin's {@code startUp}) because its
 * constructor takes collaborators that are not Guice bindings.
 *
 * <p>Runs entirely on the client thread and does only cheap, local work: a regex, a map lookup, a
 * set membership test. Anything slower is handed to the plugin executor by {@link DropPipeline}.
 */
@Slf4j
public class ChatBroadcastListener
{
	private final Client client;
	private final BingoBrazilChatConfig config;
	private final DropPipeline pipeline;
	private final Supplier<EventState> stateSupplier;

	public ChatBroadcastListener(Client client, BingoBrazilChatConfig config,
		DropPipeline pipeline, Supplier<EventState> stateSupplier)
	{
		this.client = client;
		this.config = config;
		this.pipeline = pipeline;
		this.stateSupplier = stateSupplier;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!isBroadcast(event.getType()))
		{
			return;
		}

		final String message = event.getMessage();
		Optional<ParsedBroadcast> parsed = BroadcastParser.parse(message);

		if (!parsed.isPresent())
		{
			if (config.debugLogUnmatched() && BroadcastParser.looksLikeUnparsedDrop(message))
			{
				// The one thing that turns a wording mismatch into a fixable report instead of a
				// drop that silently never scored.
				log.info("Bingo BrazilChat: unrecognised drop broadcast: {}", message);
			}
			return;
		}

		// getLocalPlayer() is client-thread-only, so it is read here and passed down rather than
		// looked up later on the executor.
		String localName = localPlayerName();

		DropPipeline.Outcome outcome = pipeline.handle(parsed.get(), stateSupplier.get(), localName);

		if (outcome == DropPipeline.Outcome.UNKNOWN_ITEM && config.debugLogUnmatched())
		{
			log.info("Bingo BrazilChat: broadcast item not in catalog: {}",
				parsed.get().getItemName());
		}
	}

	/**
	 * Only system broadcasts count.
	 *
	 * <p>{@code CLAN_CHAT} and {@code FRIENDSCHAT} are deliberately excluded: those carry text a
	 * player typed, so accepting them would let anyone score by typing a fake drop line.
	 */
	private static boolean isBroadcast(ChatMessageType type)
	{
		return type == ChatMessageType.CLAN_MESSAGE
			|| type == ChatMessageType.CLAN_GIM_MESSAGE
			|| type == ChatMessageType.CLAN_GUEST_MESSAGE;
	}

	@Nullable
	private String localPlayerName()
	{
		return client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
	}
}

package com.bingobrazilchat.chat;

import lombok.Value;

/**
 * The facts extracted from one broadcast line. Immutable and free of any RuneLite type, so the
 * parser that produces it can be unit-tested without a running client.
 */
@Value
public class ParsedBroadcast
{
	BroadcastKind kind;

	/** The dropper's name exactly as broadcast, tags and NBSP already removed but not lowercased. */
	String rsn;

	/** The item name exactly as broadcast, e.g. {@code "Kodai insignia"}. Not yet catalog-resolved. */
	String itemName;

	/** GE value in coins when the line carried one, else {@code -1}. Informational only. */
	long valueGp;

	/** Stack size when the line carried one (e.g. "587 x Cannonball"), else {@code 1}. */
	int quantity;

	/** The NPC/source the drop came from when the line named one, else {@code null}. */
	String source;

	/** The full sanitized line, forwarded to the server for audit. */
	String rawMessage;
}

package com.bingobrazilchat.event;

import com.bingobrazilchat.api.ApiDtos;
import com.bingobrazilchat.catalog.DropCatalog;
import com.bingobrazilchat.util.RsnUtil;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Value;

/**
 * An immutable snapshot of everything the last successful config fetch told us about the event.
 *
 * <p>Replaced wholesale on each refresh rather than mutated, so a broadcast handler that grabs a
 * reference mid-refresh always sees one internally consistent view.
 */
@Value
public class EventState
{
	EventWindow window;
	DropCatalog catalog;

	/** Normalised RSNs, so a name written with a hyphen still matches the roster. */
	Set<String> roster;

	ApiDtos.PolicyDto policy;

	public static EventState from(ApiDtos.ConfigResponse response, DropCatalog catalog)
	{
		Set<String> roster = new HashSet<>();
		List<String> raw = response.roster;
		if (raw != null)
		{
			for (String rsn : raw)
			{
				roster.add(RsnUtil.normalizeForCompare(rsn));
			}
		}

		EventWindow window = new EventWindow(
			response.event.id,
			response.event.name,
			parseInstant(response.event.startDate),
			parseInstant(response.event.endDate));

		return new EventState(window, catalog, Collections.unmodifiableSet(roster),
			response.policy == null ? new ApiDtos.PolicyDto() : response.policy);
	}

	public boolean isOnRoster(String rsn)
	{
		return roster.contains(RsnUtil.normalizeForCompare(rsn));
	}

	private static java.time.Instant parseInstant(String iso)
	{
		if (iso == null || iso.isEmpty())
		{
			return null;
		}
		try
		{
			return java.time.Instant.parse(iso);
		}
		catch (java.time.format.DateTimeParseException e)
		{
			// A bound we cannot read is treated as absent rather than as "closed", so a server-side
			// formatting slip cannot silently stop the whole clan from scoring.
			return null;
		}
	}
}

package com.bingobrazilchat.event;

import java.time.Instant;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * The event's start and end, as the website defines them.
 *
 * <p>Both bounds are optional on the server ({@code events.start_date} and {@code end_date} are
 * nullable), and a null bound means "unbounded in that direction" rather than "closed".
 *
 * <p>The plugin's window check is only a courtesy that avoids pointless network calls and lets the
 * panel show a countdown. The server re-checks and is authoritative.
 */
@Value
public class EventWindow
{
	String eventId;
	String name;

	@Nullable
	Instant start;

	@Nullable
	Instant end;

	public boolean isOpen(Instant now)
	{
		if (start != null && now.isBefore(start))
		{
			return false;
		}
		return end == null || !now.isAfter(end);
	}

	public boolean isBeforeStart(Instant now)
	{
		return start != null && now.isBefore(start);
	}

	public boolean isAfterEnd(Instant now)
	{
		return end != null && now.isAfter(end);
	}
}

package com.bingobrazilchat.event;

import java.time.Duration;
import java.time.Instant;

/**
 * Corrects the local clock against the server's.
 *
 * <p>Players' machine clocks are routinely minutes -- occasionally hours -- out. Since the event
 * window is a hard gate, checking it against an uncorrected local clock would silently exclude
 * someone whose PC is set wrong, and they would have no way of telling why their drops stopped
 * counting. Every config fetch carries {@code serverTime}, so the offset is free to maintain.
 *
 * <p>The offset is only ever applied to window checks and to the {@code occurredAt} we report. It
 * is deliberately <em>not</em> applied to the dedupe key, which contains no time at all.
 */
public class ServerClock
{
	/** Ignore offsets below this: they are network latency, not a wrong clock. */
	private static final long NOISE_FLOOR_MS = 2_000L;

	private volatile long offsetMillis = 0L;

	/**
	 * @param serverTime  the instant the server reported
	 * @param requestSent when we sent the request, used to discount round-trip latency
	 */
	public void sync(Instant serverTime, Instant requestSent, Instant responseReceived)
	{
		if (serverTime == null || requestSent == null || responseReceived == null)
		{
			return;
		}

		// Assume the server generated its timestamp halfway through the round trip.
		long roundTripMs = Duration.between(requestSent, responseReceived).toMillis();
		Instant localAtServerTime = requestSent.plusMillis(Math.max(0L, roundTripMs) / 2);
		long candidate = Duration.between(localAtServerTime, serverTime).toMillis();

		offsetMillis = Math.abs(candidate) < NOISE_FLOOR_MS ? 0L : candidate;
	}

	/** Local wall clock corrected by the measured offset. */
	public Instant now()
	{
		return Instant.now().plusMillis(offsetMillis);
	}

	public long getOffsetMillis()
	{
		return offsetMillis;
	}

	public boolean isSkewed()
	{
		return offsetMillis != 0L;
	}
}

package com.bingobrazilchat.submit;

import com.bingobrazilchat.api.ApiException;
import java.util.Random;

/**
 * How long to wait before trying a failed submission again.
 *
 * <p>Full jitter rather than plain exponential: a clan-wide outage would otherwise have every
 * client retry in lockstep, and the site would be hit by the whole herd at once each time.
 * Picking uniformly from {@code [0, cap]} spreads them out.
 */
public final class Backoff
{
	static final long BASE_MS = 5_000L;
	static final long CAP_MS = 15 * 60 * 1000L;

	private final Random random;

	public Backoff()
	{
		this(new Random());
	}

	/** Seeded constructor, for tests that need a deterministic sequence. */
	public Backoff(Random random)
	{
		this.random = random;
	}

	/**
	 * @param attempt      how many attempts have already failed (0 for the first failure)
	 * @param retryAfterSeconds what the server asked for, or 0 if it did not say
	 */
	public long delayMillis(int attempt, long retryAfterSeconds)
	{
		if (retryAfterSeconds > 0)
		{
			// An explicit Retry-After is the server telling us exactly when it will be ready.
			return Math.min(CAP_MS, retryAfterSeconds * 1000L);
		}

		long ceiling = ceilingFor(attempt);
		return (long) (random.nextDouble() * ceiling);
	}

	static long ceilingFor(int attempt)
	{
		int clamped = Math.max(0, Math.min(attempt, 20));
		long scaled = BASE_MS << clamped;
		// The shift overflows well past the cap for large attempt counts; guard both ways.
		return scaled <= 0 || scaled > CAP_MS ? CAP_MS : scaled;
	}

	/**
	 * Whether a failure is worth another attempt at all.
	 *
	 * <p>Getting this wrong in the permissive direction is what turns one misconfigured token into
	 * a whole clan hammering the site indefinitely.
	 */
	public static boolean shouldRetry(ApiException error)
	{
		return error.isRetryable();
	}
}

package com.bingobrazilchat.submit;

import com.bingobrazilchat.util.RsnUtil;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * The key that decides whether two reports are the same drop.
 *
 * <p>A clan broadcast is seen by every member running the plugin, so one drop produces one report
 * per online member. Those clients share nothing except what the broadcast said -- their clocks
 * routinely differ by minutes -- so the key is built purely from broadcast content and contains
 * <strong>no timestamp at all</strong>. A client-computed time bucket would split the herd whenever
 * skew straddled a boundary, and the drop would score twice.
 *
 * <p>How long two identical keys count as the same drop is decided server-side, under a lock, in
 * {@code claim_plugin_drop}. That keeps the "is this a repeat?" policy in one place.
 */
public final class DedupeKey
{
	private DedupeKey()
	{
	}

	/**
	 * @param eventId    the active event's id
	 * @param rsn        the dropper's name as broadcast; normalised here, not by the caller
	 * @param dropItemId the resolved catalog item id
	 */
	public static String of(String eventId, String rsn, String dropItemId)
	{
		String material = eventId + "|" + RsnUtil.normalizeForCompare(rsn) + "|" + dropItemId;
		return sha256Hex(material);
	}

	private static String sha256Hex(String input)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder(hash.length * 2);
			for (byte b : hash)
			{
				sb.append(Character.forDigit((b >> 4) & 0xF, 16));
				sb.append(Character.forDigit(b & 0xF, 16));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			// SHA-256 is required of every JVM; if it is genuinely absent nothing here can work.
			throw new IllegalStateException("SHA-256 unavailable", e);
		}
	}
}

package com.bingobrazilchat.submit;

import com.bingobrazilchat.BingoBrazilChatConfig;
import com.bingobrazilchat.capture.ScreenshotService;
import com.bingobrazilchat.catalog.CatalogItem;
import com.bingobrazilchat.chat.ParsedBroadcast;
import com.bingobrazilchat.event.EventState;
import com.bingobrazilchat.event.ServerClock;
import com.bingobrazilchat.util.RsnUtil;
import java.time.Instant;
import java.util.Optional;
import java.util.Random;
import java.util.concurrent.ScheduledExecutorService;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * Decides what happens to a parsed broadcast: ignore it, or turn it into a queued submission.
 *
 * <p>The ordering of the checks is deliberate -- everything cheap and local runs before anything
 * that could reach the network, so an ordinary clan broadcast for an item nobody is tracking costs
 * a couple of map lookups and nothing else.
 */
@Slf4j
public class DropPipeline
{
	private final ScheduledExecutorService executor;
	private final ScreenshotService screenshots;
	private final SubmissionQueue queue;
	private final QueuePersistence persistence;
	private final BingoBrazilChatConfig config;
	private final ServerClock clock;
	private final Random random = new Random();

	public DropPipeline(
		ScheduledExecutorService executor,
		ScreenshotService screenshots,
		SubmissionQueue queue,
		QueuePersistence persistence,
		BingoBrazilChatConfig config,
		ServerClock clock)
	{
		this.executor = executor;
		this.screenshots = screenshots;
		this.queue = queue;
		this.persistence = persistence;
		this.config = config;
		this.clock = clock;
	}

	/**
	 * Called from the chat handler, on the client thread. Returns quickly; anything slow is handed
	 * to the executor.
	 *
	 * @param localPlayerName the account this client is logged in as, read on the client thread by
	 *                        the caller because {@code getLocalPlayer()} is client-thread-only
	 * @return an outcome, purely so the caller can decide what to log
	 */
	public Outcome handle(ParsedBroadcast broadcast, @Nullable EventState state,
		@Nullable String localPlayerName)
	{
		if (state == null)
		{
			return Outcome.NOT_READY;
		}

		Optional<CatalogItem> match = state.getCatalog().lookup(broadcast.getItemName());
		if (!match.isPresent())
		{
			return state.getCatalog().isKnownIgnored(broadcast.getItemName())
				? Outcome.NOT_SCOREABLE
				: Outcome.UNKNOWN_ITEM;
		}

		if (!state.isOnRoster(broadcast.getRsn()))
		{
			// Someone in the clan who is not in the event. Nothing to do, and no network call.
			return Outcome.NOT_ON_ROSTER;
		}

		Instant now = clock.now();
		if (!state.getWindow().isOpen(now))
		{
			// The server would reject this anyway; refusing here avoids a pointless round trip and
			// keeps the panel from filling with rejections outside the event.
			return state.getWindow().isBeforeStart(now)
				? Outcome.BEFORE_EVENT
				: Outcome.AFTER_EVENT;
		}

		boolean isSelf = localPlayerName != null
			&& RsnUtil.normalizeForCompare(localPlayerName)
			.equals(RsnUtil.normalizeForCompare(broadcast.getRsn()));

		if (!isSelf && !config.enableObserverReports())
		{
			return Outcome.OBSERVER_DISABLED;
		}

		CatalogItem item = match.get();
		QueuedSubmission submission = build(broadcast, state, item, now, isSelf, localPlayerName);

		// The screenshot is taken NOW even for an observer report whose claim is delayed: by the
		// time the delay elapses the chatbox has scrolled and the moment is gone. If the claim then
		// comes back as a duplicate, the held image is simply discarded.
		long delay = isSelf ? 0L : observerDelayMillis(state);

		if (config.captureScreenshot())
		{
			screenshots.capture(executor, config.screenshotScalePercent(),
				state.getPolicy().maxProofBytes, png ->
				{
					if (png != null)
					{
						persistence.writeProof(submission.getDedupeKey(), png);
						submission.setHasProof(true);
					}
					queue.enqueue(submission, delay);
				});
		}
		else
		{
			queue.enqueue(submission, delay);
		}

		return isSelf ? Outcome.QUEUED_SELF : Outcome.QUEUED_OBSERVER;
	}

	private QueuedSubmission build(ParsedBroadcast broadcast, EventState state, CatalogItem item,
		Instant now, boolean isSelf, @Nullable String localPlayerName)
	{
		QueuedSubmission s = new QueuedSubmission();
		s.setDedupeKey(DedupeKey.of(state.getWindow().getEventId(), broadcast.getRsn(),
			item.getDropItemId()));
		s.setEventId(state.getWindow().getEventId());
		s.setRsn(broadcast.getRsn());
		s.setDropItemId(item.getDropItemId());
		s.setItemDisplayName(item.getCatalogName());
		s.setPoints(item.getPoints());
		s.setItemNameRaw(broadcast.getItemName());
		s.setBroadcastType(broadcast.getKind().getWireName());
		s.setRawMessage(broadcast.getRawMessage());
		s.setOccurredAt(now.toString());
		s.setObserver(!isSelf);
		// Falls back to the dropper's own name when we somehow have no local player: the server
		// only uses this to make a retry from the same client idempotent.
		s.setReporterRsn(localPlayerName == null ? broadcast.getRsn() : localPlayerName);
		s.setState(SubmissionState.PENDING_CLAIM);
		return s;
	}

	/**
	 * How long an observer waits before reporting someone else's drop.
	 *
	 * <p>The point is to let the player who actually got the drop claim it first, so the screenshot
	 * that ends up attached is theirs. The jitter then spreads the remaining clients out instead of
	 * having twenty of them fire at the same instant once the delay elapses.
	 */
	private long observerDelayMillis(EventState state)
	{
		long base = Math.max(0L, state.getPolicy().observerDelayMs);
		long jitter = Math.max(0L, state.getPolicy().observerJitterMs);
		return base + (jitter == 0L ? 0L : (long) (random.nextDouble() * jitter));
	}

	/** What the pipeline decided, so the caller can log or announce appropriately. */
	public enum Outcome
	{
		QUEUED_SELF,
		QUEUED_OBSERVER,
		NOT_READY,
		UNKNOWN_ITEM,
		NOT_SCOREABLE,
		NOT_ON_ROSTER,
		BEFORE_EVENT,
		AFTER_EVENT,
		OBSERVER_DISABLED
	}
}

package com.bingobrazilchat.submit;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.lang.reflect.Type;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;

/**
 * Keeps the queue across restarts, split across two stores for a reason.
 *
 * <p>Metadata goes into RuneLite config as one JSON blob: small, and it survives a crash. It is
 * written at <em>plugin-group</em> scope rather than RS-profile scope on purpose -- an observer
 * entry belongs to the client, not to the account that happens to be logged in, so switching
 * accounts must not orphan a pending drop.
 *
 * <p>Screenshot bytes go to files under the RuneLite directory. They are far too large to sit in a
 * config value that gets rewritten on every state change.
 */
@Slf4j
public class QueuePersistence
{
	private static final String CONFIG_KEY = "queue";
	private static final String SUBDIR = "bingo-brazilchat/queue";
	private static final long ORPHAN_MAX_AGE_MS = TimeUnit.HOURS.toMillis(24);

	private final ConfigManager configManager;
	private final Gson gson;
	private final File proofDir;

	public QueuePersistence(ConfigManager configManager, Gson gson)
	{
		this(configManager, gson, new File(RuneLite.RUNELITE_DIR, SUBDIR));
	}

	/** Test seam: lets a unit test point the proof directory somewhere disposable. */
	QueuePersistence(ConfigManager configManager, Gson gson, File proofDir)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.proofDir = proofDir;
	}

	public List<QueuedSubmission> load()
	{
		if (configManager == null)
		{
			return new ArrayList<>();
		}

		String raw = configManager.getConfiguration(
			com.bingobrazilchat.BingoBrazilChatConfig.GROUP, CONFIG_KEY);
		if (raw == null || raw.trim().isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			Type type = new TypeToken<List<QueuedSubmission>>()
			{
			}.getType();
			List<QueuedSubmission> loaded = gson.fromJson(raw, type);
			return loaded == null ? new ArrayList<>() : loaded;
		}
		catch (JsonSyntaxException e)
		{
			// A corrupt blob must not stop the plugin loading; losing a queued drop is the lesser
			// harm, and the alternative is the plugin refusing to start at all.
			log.warn("Bingo BrazilChat: discarding unreadable queue", e);
			return new ArrayList<>();
		}
	}

	public void save(List<QueuedSubmission> queue)
	{
		if (configManager == null)
		{
			return;
		}
		configManager.setConfiguration(
			com.bingobrazilchat.BingoBrazilChatConfig.GROUP, CONFIG_KEY, gson.toJson(queue));
	}

	public void writeProof(String dedupeKey, byte[] png)
	{
		try
		{
			//noinspection ResultOfMethodCallIgnored
			proofDir.mkdirs();
			Files.write(proofFile(dedupeKey).toPath(), png);
		}
		catch (IOException e)
		{
			// A missing screenshot is a degraded submission, not a failed one -- the drop still
			// scores, it just has no image.
			log.warn("Bingo BrazilChat: could not store screenshot for {}", dedupeKey, e);
		}
	}

	@Nullable
	public byte[] readProof(String dedupeKey)
	{
		File file = proofFile(dedupeKey);
		if (!file.isFile())
		{
			return null;
		}
		try
		{
			return Files.readAllBytes(file.toPath());
		}
		catch (IOException e)
		{
			log.warn("Bingo BrazilChat: could not read screenshot for {}", dedupeKey, e);
			return null;
		}
	}

	public void deleteProof(String dedupeKey)
	{
		File file = proofFile(dedupeKey);
		if (file.isFile() && !file.delete())
		{
			log.debug("Bingo BrazilChat: could not delete screenshot for {}", dedupeKey);
		}
	}

	/**
	 * Removes screenshots with no queue entry left, and anything older than a day. Without this the
	 * directory grows without bound whenever a client is killed between writing an image and
	 * finishing the upload.
	 */
	public void sweep(List<QueuedSubmission> queue)
	{
		File[] files = proofDir.listFiles();
		if (files == null)
		{
			return;
		}

		Set<String> live = new HashSet<>();
		for (QueuedSubmission s : queue)
		{
			if (!s.getState().isTerminal())
			{
				live.add(s.getDedupeKey() + ".png");
			}
		}

		long cutoff = System.currentTimeMillis() - ORPHAN_MAX_AGE_MS;
		for (File file : files)
		{
			if (!live.contains(file.getName()) || file.lastModified() < cutoff)
			{
				//noinspection ResultOfMethodCallIgnored
				file.delete();
			}
		}
	}

	private File proofFile(String dedupeKey)
	{
		return new File(proofDir, dedupeKey + ".png");
	}
}

package com.bingobrazilchat.submit;

import lombok.Data;

/**
 * One drop on its way to the site.
 *
 * <p>Mutable and Gson-friendly on purpose: instances are serialised straight into RuneLite config
 * so a client restart mid-event does not lose a drop. The screenshot bytes are deliberately
 * <em>not</em> a field -- they live in a file next to the queue, keyed by {@link #dedupeKey},
 * because a base64 image inside a config value would be both huge and slow to rewrite on every
 * state change.
 */
@Data
public class QueuedSubmission
{
	/** Stable across retries and identical on every client that saw this broadcast. */
	private String dedupeKey;

	private String eventId;

	/** The dropper. */
	private String rsn;

	private String dropItemId;

	/** For the panel, so a queued row can name the item without a catalog lookup. */
	private String itemDisplayName;

	private int points;

	private String itemNameRaw;
	private String broadcastType;
	private String rawMessage;

	/** ISO-8601 UTC, server-clock corrected. */
	private String occurredAt;

	/** True when we are reporting someone else's drop rather than our own. */
	private boolean observer;

	/** Whichever account this client is logged in as; the server's retry guard keys on it. */
	private String reporterRsn;

	private SubmissionState state = SubmissionState.PENDING_CLAIM;

	/** Failed attempts so far, driving the backoff ceiling. */
	private int attempt;

	/** Epoch millis before which this should not be tried again. */
	private long nextAttemptAtMillis;

	/** Epoch millis after which we give up entirely. */
	private long expiresAtMillis;

	/** Set once the claim succeeds. */
	private String submissionId;

	private String proofToken;

	/** True while a screenshot for this key is still on disk waiting to be uploaded. */
	private boolean hasProof;

	/** Why a terminal state was reached, shown in the panel. */
	private String statusDetail;

	public boolean isDue(long nowMillis)
	{
		return !state.isTerminal() && nowMillis >= nextAttemptAtMillis;
	}

	public boolean isExpired(long nowMillis)
	{
		return expiresAtMillis > 0 && nowMillis > expiresAtMillis;
	}
}

package com.bingobrazilchat.submit;

import com.bingobrazilchat.api.ApiCallback;
import com.bingobrazilchat.api.ApiDtos;
import com.bingobrazilchat.api.ApiException;
import com.bingobrazilchat.api.BingoApiClient;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

/**
 * Drives every submission from "a broadcast happened" to a terminal state.
 *
 * <p><b>Threading:</b> every method here runs on the plugin's own single-threaded executor. That is
 * the entire concurrency design -- because all queue mutation happens on one thread, none of this
 * state needs locks. API callbacks arrive on OkHttp dispatcher threads and immediately hop back via
 * {@code executor.execute(...)}; nothing else may touch the queue.
 *
 * <p><b>The herd:</b> no attempt is made to elect a single reporter. Every client submits and the
 * server collapses them, because leader election would be fragile and would lose the drop entirely
 * whenever the elected client was the one not running the plugin.
 */
@Slf4j
public class SubmissionQueue
{
	/** How often to look for work. Backoff decides when an individual item is actually due. */
	private static final long PUMP_INTERVAL_SECONDS = 5L;

	/** How long one client remembers a drop it already handled, so it cannot submit it twice. */
	private static final long SEEN_TTL_MS = TimeUnit.MINUTES.toMillis(15);

	/** Nothing is retried forever, even if the event is still open. */
	private static final long MAX_LIFETIME_MS = TimeUnit.HOURS.toMillis(24);

	private final ScheduledExecutorService executor;
	private final BingoApiClient api;
	private final QueuePersistence persistence;
	private final Backoff backoff;
	private final Consumer<List<QueuedSubmission>> onChanged;
	private final Consumer<QueuedSubmission> onRecorded;

	private final List<QueuedSubmission> queue = new ArrayList<>();
	private final Map<String, Long> seen = new HashMap<>();

	/** Guards against two pumps overlapping if a call outlives the interval. */
	private boolean pumping = false;

	public SubmissionQueue(
		ScheduledExecutorService executor,
		BingoApiClient api,
		QueuePersistence persistence,
		Backoff backoff,
		Consumer<List<QueuedSubmission>> onChanged,
		Consumer<QueuedSubmission> onRecorded)
	{
		this.executor = executor;
		this.api = api;
		this.persistence = persistence;
		this.backoff = backoff;
		this.onChanged = onChanged;
		this.onRecorded = onRecorded;
	}

	/** Restores anything left over from a previous session and starts the retry pump. */
	public void start()
	{
		executor.execute(() ->
		{
			queue.clear();
			queue.addAll(persistence.load());

			long now = System.currentTimeMillis();
			for (QueuedSubmission s : queue)
			{
				// Anything mid-flight when the client died is due again immediately; there is no
				// value in honouring a backoff that was measured against a previous session.
				if (!s.getState().isTerminal())
				{
					s.setNextAttemptAtMillis(now);
					seen.put(s.getDedupeKey(), now + SEEN_TTL_MS);
				}
			}

			persistence.sweep(queue);
			notifyChanged();
			log.debug("Bingo BrazilChat: restored {} queued submissions", queue.size());
		});

		executor.scheduleWithFixedDelay(this::pump,
			PUMP_INTERVAL_SECONDS, PUMP_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * Adds a submission unless this client already handled that exact drop.
	 *
	 * @param delayMillis how long to hold it before the first attempt; non-zero for observer
	 *                    reports, so the person who actually got the drop reports it first
	 */
	public void enqueue(QueuedSubmission submission, long delayMillis)
	{
		executor.execute(() ->
		{
			long now = System.currentTimeMillis();
			expireSeen(now);

			if (seen.containsKey(submission.getDedupeKey()))
			{
				// This client already has this drop in hand. The server would collapse it anyway,
				// but not sending it at all is cheaper and keeps the panel honest.
				log.debug("Bingo BrazilChat: already handling {}", submission.getDedupeKey());
				return;
			}

			submission.setNextAttemptAtMillis(now + Math.max(0L, delayMillis));
			submission.setExpiresAtMillis(now + MAX_LIFETIME_MS);
			seen.put(submission.getDedupeKey(), now + SEEN_TTL_MS);

			queue.add(submission);
			persist();
			notifyChanged();
		});
	}

	/** Caps how long anything is retried, so a queue cannot outlive the event by more than an hour. */
	public void setEventEnd(long eventEndMillis)
	{
		executor.execute(() ->
		{
			long deadline = eventEndMillis + TimeUnit.HOURS.toMillis(1);
			for (QueuedSubmission s : queue)
			{
				if (!s.getState().isTerminal())
				{
					s.setExpiresAtMillis(Math.min(s.getExpiresAtMillis(), deadline));
				}
			}
		});
	}

	public void clearTerminal()
	{
		executor.execute(() ->
		{
			queue.removeIf(s -> s.getState().isTerminal());
			persist();
			notifyChanged();
		});
	}

	public List<QueuedSubmission> snapshot()
	{
		return Collections.unmodifiableList(new ArrayList<>(queue));
	}

	// ------------------------------------------------------------------------------------------

	private void pump()
	{
		if (pumping || !api.isConfigured())
		{
			return;
		}

		long now = System.currentTimeMillis();
		expireSeen(now);

		QueuedSubmission due = null;
		for (QueuedSubmission s : queue)
		{
			if (s.isExpired(now) && !s.getState().isTerminal())
			{
				fail(s, "Gave up after " + s.getAttempt() + " attempts");
				continue;
			}
			if (s.isDue(now))
			{
				due = s;
				break;
			}
		}

		if (due == null)
		{
			return;
		}

		pumping = true;
		if (due.getState() == SubmissionState.PENDING_CLAIM)
		{
			sendClaim(due);
		}
		else
		{
			sendProof(due);
		}
	}

	private void sendClaim(QueuedSubmission s)
	{
		ApiDtos.ClaimRequest req = new ApiDtos.ClaimRequest();
		req.eventId = s.getEventId();
		req.rsn = s.getRsn();
		req.dropItemId = s.getDropItemId();
		req.itemNameRaw = s.getItemNameRaw();
		req.broadcastType = s.getBroadcastType();
		req.rawMessage = s.getRawMessage();
		req.occurredAt = s.getOccurredAt();
		req.observer = s.isObserver();
		req.reporterRsn = s.getReporterRsn();
		req.dedupeKey = s.getDedupeKey();
		req.hasProof = s.isHasProof();

		api.claimDrop(req, new ApiCallback<ApiDtos.ClaimResponse>()
		{
			@Override
			public void onSuccess(ApiDtos.ClaimResponse result)
			{
				executor.execute(() -> onClaimResult(s, result));
			}

			@Override
			public void onFailure(ApiException error)
			{
				executor.execute(() -> onAttemptFailed(s, error));
			}
		});
	}

	private void onClaimResult(QueuedSubmission s, ApiDtos.ClaimResponse result)
	{
		pumping = false;

		if (result.isRejected())
		{
			s.setState(SubmissionState.REJECTED);
			s.setStatusDetail(describeRejection(result.reason));
			finish(s);
			return;
		}

		if (result.isDuplicate())
		{
			// Someone else's client reported it first. That is a success: the drop is on the board.
			s.setState(SubmissionState.DUPLICATE);
			s.setSubmissionId(result.submissionId);
			finish(s);
			return;
		}

		if (!result.isCreated() || result.submissionId == null)
		{
			onAttemptFailed(s, ApiException.transport("Unexpected claim status: " + result.status));
			return;
		}

		s.setSubmissionId(result.submissionId);
		s.setProofToken(result.proofUploadToken);
		if (result.itemName != null)
		{
			s.setItemDisplayName(result.itemName);
			s.setPoints(result.points);
		}

		byte[] proof = s.isHasProof() ? persistence.readProof(s.getDedupeKey()) : null;
		if (proof == null || s.getProofToken() == null)
		{
			// No screenshot to attach: the drop is recorded, which is what matters.
			s.setState(SubmissionState.DONE);
			finish(s);
			return;
		}

		s.setState(SubmissionState.AWAITING_PROOF);
		s.setAttempt(0);
		s.setNextAttemptAtMillis(System.currentTimeMillis());
		persist();
		notifyChanged();
	}

	private void sendProof(QueuedSubmission s)
	{
		byte[] proof = persistence.readProof(s.getDedupeKey());
		if (proof == null || s.getSubmissionId() == null || s.getProofToken() == null)
		{
			s.setState(SubmissionState.DONE);
			finish(s);
			pumping = false;
			return;
		}

		s.setState(SubmissionState.UPLOADING_PROOF);
		api.uploadProof(s.getSubmissionId(), s.getProofToken(), proof, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
				executor.execute(() ->
				{
					pumping = false;
					s.setState(SubmissionState.DONE);
					finish(s);
				});
			}

			@Override
			public void onFailure(ApiException error)
			{
				executor.execute(() ->
				{
					if (!Backoff.shouldRetry(error))
					{
						// The row exists and scores; only the image failed. Not worth failing over.
						log.debug("Bingo BrazilChat: giving up on proof for {}", s.getDedupeKey());
						pumping = false;
						s.setState(SubmissionState.DONE);
						s.setStatusDetail("Recorded without a screenshot");
						finish(s);
						return;
					}
					s.setState(SubmissionState.AWAITING_PROOF);
					onAttemptFailed(s, error);
				});
			}
		});
	}

	private void onAttemptFailed(QueuedSubmission s, ApiException error)
	{
		pumping = false;

		if (!Backoff.shouldRetry(error))
		{
			fail(s, error.isAuthFailure()
				? "Check your event token in the plugin settings"
				: error.getMessage());
			return;
		}

		s.setAttempt(s.getAttempt() + 1);
		long delay = backoff.delayMillis(s.getAttempt(), error.getRetryAfterSeconds());
		s.setNextAttemptAtMillis(System.currentTimeMillis() + delay);
		s.setStatusDetail("Retrying");

		log.debug("Bingo BrazilChat: attempt {} failed for {}, retrying in {}ms",
			s.getAttempt(), s.getDedupeKey(), delay);

		persist();
		notifyChanged();
	}

	private void fail(QueuedSubmission s, String detail)
	{
		s.setState(SubmissionState.FAILED);
		s.setStatusDetail(detail);
		finish(s);
	}

	/** Terminal states release the screenshot, which is the only large thing we hold. */
	private void finish(QueuedSubmission s)
	{
		persistence.deleteProof(s.getDedupeKey());
		s.setHasProof(false);
		persist();
		notifyChanged();

		// Only announce a drop this client actually put on the board. A DUPLICATE means someone
		// else's client got there first, and every one of them announcing it would mean the whole
		// clan seeing the same line for one drop.
		if (s.getState() == SubmissionState.DONE && onRecorded != null)
		{
			onRecorded.accept(s);
		}
	}

	private void expireSeen(long now)
	{
		Iterator<Map.Entry<String, Long>> it = seen.entrySet().iterator();
		while (it.hasNext())
		{
			if (it.next().getValue() < now)
			{
				it.remove();
			}
		}
	}

	private void persist()
	{
		persistence.save(queue);
	}

	private void notifyChanged()
	{
		if (onChanged != null)
		{
			onChanged.accept(snapshot());
		}
	}

	private static String describeRejection(String reason)
	{
		if (reason == null)
		{
			return "Not counted";
		}
		switch (reason)
		{
			case "event_not_started":
				return "The event has not started yet";
			case "event_ended":
				return "The event has already ended";
			case "player_not_registered":
				return "That player is not on the event roster";
			case "item_not_in_catalog":
				return "That item does not score in this event";
			default:
				return "Not counted (" + reason + ")";
		}
	}
}

package com.bingobrazilchat.submit;

/**
 * Where a queued submission has got to. Only {@link #PENDING_CLAIM} and {@link #UPLOADING_PROOF}
 * are retried; everything else is terminal and stays visible in the panel so a player can see what
 * happened rather than watching a drop disappear.
 */
public enum SubmissionState
{
	/** Waiting to tell the server this drop happened. */
	PENDING_CLAIM("Sending"),

	/** The claim succeeded and this client owns the proof upload. */
	AWAITING_PROOF("Attaching proof"),

	/** Uploading the screenshot. */
	UPLOADING_PROOF("Attaching proof"),

	/** Recorded, with proof attached. */
	DONE("Recorded"),

	/** Someone else's client got there first. Still a success -- the drop is on the board. */
	DUPLICATE("Already recorded"),

	/** The server understood us and declined: outside the window, not on the roster, not scoreable. */
	REJECTED("Not counted"),

	/** Gave up. The reason is kept alongside so the panel can explain it. */
	FAILED("Failed");

	private final String label;

	SubmissionState(String label)
	{
		this.label = label;
	}

	public String getLabel()
	{
		return label;
	}

	public boolean isTerminal()
	{
		return this == DONE || this == DUPLICATE || this == REJECTED || this == FAILED;
	}
}

