		queuePanel.setLayout(new BoxLayout(queuePanel, BoxLayout.Y_AXIS));
		queuePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		queuePanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(queuePanel);

		content.add(Box.createRigidArea(new Dimension(0, 8)));
		clearButton.setFocusPainted(false);
		clearButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		clearButton.addActionListener(e -> onClearFinished.run());
		content.add(clearButton);

		add(new javax.swing.JScrollPane(content,
			javax.swing.ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			javax.swing.ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER), BorderLayout.CENTER);

		// The countdown is the one thing that has to change without any new data arriving.
		countdownTimer = new Timer(1000, e -> refreshCountdown());
		countdownTimer.start();

		render();
	}

	/** Safe to call from any thread. */
	public void setState(PanelState next)
	{
		SwingUtilities.invokeLater(() ->
		{
			this.state = next;
			render();
		});
	}

	public void shutdown()
	{
		countdownTimer.stop();
	}

	// ------------------------------------------------------------------------------------------

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new GridLayout(0, 1, 0, 2));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);

		statusLabel.setFont(FontManager.getRunescapeBoldFont());
		detailLabel.setFont(FontManager.getRunescapeSmallFont());
		detailLabel.setForeground(MUTED);
		eventNameLabel.setFont(FontManager.getRunescapeSmallFont());
		eventNameLabel.setForeground(Color.WHITE);
		countdownLabel.setFont(FontManager.getRunescapeSmallFont());
		countdownLabel.setForeground(MUTED);

		header.add(statusLabel);
		header.add(detailLabel);
		header.add(eventNameLabel);
		header.add(countdownLabel);
		return header;
	}

	private static JLabel buildSectionLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private void render()
	{
		statusLabel.setText(state.getConnection().getLabel());
		statusLabel.setForeground(colourFor(state.getConnection()));

		String detail = state.getDetail();
		if (state.getConnection() == PanelState.Connection.NOT_CONFIGURED && detail == null)
		{
			detail = "Enter your event token in the plugin settings";
		}
		detailLabel.setText(detail == null ? " " : detail);

		EventWindow window = state.getWindow();
		eventNameLabel.setText(window == null ? " " : window.getName());

		refreshCountdown();
		renderTeams();
		renderQueue();

		revalidate();
		repaint();
	}

	private void renderTeams()
	{
		teamsPanel.removeAll();

		List<ApiDtos.TeamRow> teams = state.getTeams();
		if (teams.isEmpty())
		{
			teamsPanel.add(mutedRow("No scores yet"));
		}
		else
		{
			for (ApiDtos.TeamRow team : teams)
			{
				teamsPanel.add(buildTeamRow(team));
				teamsPanel.add(Box.createRigidArea(new Dimension(0, 3)));
			}
		}

		teamsPanel.revalidate();
		teamsPanel.repaint();
	}

	private JPanel buildTeamRow(ApiDtos.TeamRow team)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));

		JLabel name = new JLabel(team.rank + ". " + team.name);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(parseColour(team.color));

		JLabel points = new JLabel(team.points + " pts");
		points.setFont(FontManager.getRunescapeSmallFont());
		points.setForeground(Color.WHITE);

		row.add(name, BorderLayout.CENTER);
		row.add(points, BorderLayout.EAST);
		return row;
	}

	private void renderQueue()
	{
		queuePanel.removeAll();

		List<QueuedSubmission> queue = state.getQueue();
		if (queue.isEmpty())
		{
			queuePanel.add(mutedRow("Nothing sent yet"));
		}
		else
		{
			// Newest first: the drop someone just got is the one they want to see.
			for (int i = queue.size() - 1; i >= 0; i--)
			{
				queuePanel.add(buildQueueRow(queue.get(i)));
				queuePanel.add(Box.createRigidArea(new Dimension(0, 3)));
			}
		}

		clearButton.setEnabled(queue.stream().anyMatch(s -> s.getState().isTerminal()));

		queuePanel.revalidate();
		queuePanel.repaint();
	}

	private JPanel buildQueueRow(QueuedSubmission submission)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		String itemName = submission.getItemDisplayName() == null
			? submission.getItemNameRaw()
			: submission.getItemDisplayName();

		JLabel title = new JLabel(submission.getRsn() + " - " + itemName);
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);

		String statusText = submission.getState().getLabel();
		if (submission.getStatusDetail() != null && !submission.getStatusDetail().isEmpty())
		{
			statusText = statusText + " - " + submission.getStatusDetail();
		}

		JLabel status = new JLabel(statusText);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(colourFor(submission.getState()));
		status.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(title);
		row.add(status);
		return row;
	}

	private void refreshCountdown()
	{
		EventWindow window = state.getWindow();
		if (window == null)
		{
			countdownLabel.setText(" ");
			return;
		}

		Instant now = Instant.now();
		if (window.isBeforeStart(now))
		{
			countdownLabel.setText("Starts in " + humanise(Duration.between(now, window.getStart())));
		}
		else if (window.isAfterEnd(now))
		{
			countdownLabel.setText("Event finished");
		}
		else if (window.getEnd() != null)
		{
			countdownLabel.setText("Ends in " + humanise(Duration.between(now, window.getEnd())));
		}
		else
		{
			countdownLabel.setText("Running");
		}
	}

	private static String humanise(Duration d)
	{
		long seconds = Math.max(0L, d.getSeconds());
		long days = seconds / 86_400L;
		long hours = (seconds % 86_400L) / 3_600L;
		long minutes = (seconds % 3_600L) / 60L;

		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		return minutes + "m " + (seconds % 60L) + "s";
	}

	private static JLabel mutedRow(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static Color colourFor(PanelState.Connection connection)
	{
		switch (connection)
		{
			case ONLINE:
				return POSITIVE;
			case UNAUTHORIZED:
			case OFFLINE:
				return NEGATIVE;
			case NO_EVENT:
			case CONNECTING:
				return WARNING;
			default:
				return MUTED;
		}
	}

	private static Color colourFor(SubmissionState state)
	{
		switch (state)
		{
			case DONE:
			case DUPLICATE:
				return POSITIVE;
			case FAILED:
				return NEGATIVE;
			case REJECTED:
				return WARNING;
			default:
				return MUTED;
		}
	}

	private static Color parseColour(String hex)
	{
		if (hex == null || hex.isEmpty())
		{
			return Color.WHITE;
		}
		try
		{
			return Color.decode(hex.startsWith("#") ? hex : "#" + hex);
		}
		catch (NumberFormatException e)
		{
			return Color.WHITE;
		}
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(PluginPanel.PANEL_WIDTH, super.getPreferredSize().height);
	}
}

package com.bingobrazilchat.ui;

import com.bingobrazilchat.api.ApiDtos;
import com.bingobrazilchat.event.EventWindow;
import com.bingobrazilchat.submit.QueuedSubmission;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * An immutable snapshot handed to the panel.
 *
 * <p>The panel runs on the EDT and everything that produces this runs on the plugin executor, so
 * passing a whole snapshot rather than letting the panel read live state is what keeps the two
 * threads from tripping over each other.
 */
@Value
public class PanelState
{
	public enum Connection
	{
		/** No token entered: the plugin is intentionally doing nothing. */
		NOT_CONFIGURED("Not set up"),
		/** Token entered, no successful fetch yet. */
		CONNECTING("Connecting"),
		/** Talking to the site. */
		ONLINE("Connected"),
		/** The token was rejected. */
		UNAUTHORIZED("Token rejected"),
		/** Reachable config, but no event is currently active. */
		NO_EVENT("No active event"),
		/** Cannot reach the site. */
		OFFLINE("Offline");

		private final String label;

		Connection(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	Connection connection;

	@Nullable
	String detail;

	@Nullable
	EventWindow window;

	List<ApiDtos.TeamRow> teams;

	List<QueuedSubmission> queue;

	/** True when the local clock is far enough out that we are correcting for it. */
	boolean clockSkewed;

	public static PanelState initial()
	{
		return new PanelState(Connection.NOT_CONFIGURED, null, null,
			Collections.emptyList(), Collections.emptyList(), false);
	}
}

package com.bingobrazilchat.util;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * RSN handling, split deliberately into two operations that must never be confused.
 *
 * <p>{@link #normalizeForCompare(String)} produces the key used for roster lookups and for the
 * dedupe hash. It has to match the server's rule exactly, or every client computes a different
 * dedupe key and the herd never collapses into one scored drop.
 *
 * <p>The RSN itself is sent to the server <em>unmodified</em>. Notably we do not use RuneLite's
 * {@code Text.toJagexName}, which replaces {@code -} and {@code _} with spaces: the
 * {@code players.rsn} column allows both characters, so that would corrupt real names.
 */
public final class RsnUtil
{
	private static final Pattern SEPARATORS = Pattern.compile("[-_ ]");
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	/** Mirrors the RSN rule the server validates with, so junk is rejected before any network call. */
	private static final Pattern VALID_RSN = Pattern.compile("^[a-zA-Z0-9 _-]{1,12}$");

	private RsnUtil()
	{
	}

	public static String normalizeForCompare(String rsn)
	{
		if (rsn == null)
		{
			return "";
		}
		String s = SEPARATORS.matcher(rsn).replaceAll(" ");
		s = WHITESPACE.matcher(s).replaceAll(" ").trim();
		// Locale.ROOT, not the default locale: on a Turkish-locale machine the default maps 'I' to
		// the dotless 'i' and every roster lookup silently misses.
		return s.toLowerCase(Locale.ROOT);
	}

	public static boolean isValid(String rsn)
	{
		return rsn != null && VALID_RSN.matcher(rsn).matches();
	}
}

package com.bingobrazilchat.util;

import java.text.Normalizer;
import java.util.regex.Pattern;

/**
 * Scrubs a raw chat line down to the plain text a regex can anchor on.
 *
 * <p>Every broadcast pattern in this plugin anchors on {@code ^}, so anything the client renders as
 * nothing but still leaves in the string will silently break matching. Three such things exist:
 * markup tags ({@code <col=ef20ff>}, {@code </col>}, {@code <img=2>}), chat colour tokens
 * ({@code @red@}), and the machine-readable metadata Jagex prefixes some broadcasts with
 * ({@code CA_ID:112|...}). All three are removed here, in that order -- the metadata prefix goes
 * last because it can sit *behind* a colour span, so it only reaches the start of the string once
 * the tags are gone.
 */
public final class Sanitizer
{
	private static final Pattern TAGS_AND_TOKENS = Pattern.compile("(<[^>]*>)|(@[^@\\s]+@)");
	private static final Pattern METADATA_PREFIX = Pattern.compile("^(?:[A-Z][A-Z0-9_]*:\\d+\\|)+");
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	private static final char NBSP = ' ';
	private static final char RIGHT_SINGLE_QUOTE = '’';
	private static final char LEFT_SINGLE_QUOTE = '‘';

	private Sanitizer()
	{
	}

	public static String clean(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		String s = raw.replace("<br>", " ");
		s = TAGS_AND_TOKENS.matcher(s).replaceAll("");
		// OSRS renders display names with non-breaking spaces; without this fold, any RSN with a
		// space in it fails to match a pattern written with ordinary spaces.
		s = s.replace(NBSP, ' ');
		s = Normalizer.normalize(s, Normalizer.Form.NFKC);
		// Typographic apostrophes would break "Osmumten's fang" / "Elidinis' ward" lookups.
		s = s.replace(RIGHT_SINGLE_QUOTE, '\'').replace(LEFT_SINGLE_QUOTE, '\'');
		s = WHITESPACE.matcher(s).replaceAll(" ").trim();

		return METADATA_PREFIX.matcher(s).replaceAll("").trim();
	}
}

package com.bingobrazilchat;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BingoBrazilChatPluginTest
{
	public static void main(String[] args) throws Exception
	{
		// Isolate the dev client to its own RuneLite home BEFORE any RuneLite class loads
