}

package com.bingobrazilchat.catalog;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The catalog is where a wrong assumption costs points silently: an unresolved item simply never
 * scores. Every alias in the shipped table is asserted here.
 */
public class DropCatalogTest
{
	private DropCatalog catalog;

	/** Mirrors the website's seed catalog, with stable fake ids. */
	private static List<CatalogItem> seedItems()
	{
		List<CatalogItem> items = new ArrayList<>();
		items.add(new CatalogItem("cox-tbow", "Twisted Bow", "cox", 20));
		items.add(new CatalogItem("cox-kodai", "Kodai Wand", "cox", 6));
		items.add(new CatalogItem("cox-maul", "Elder Maul", "cox", 6));
		items.add(new CatalogItem("cox-dex", "Dexterous Prayer Scroll", "cox", 2));
		items.add(new CatalogItem("cox-claws", "Dragon Claws", "cox", 4));
		items.add(new CatalogItem("cox-anc-top", "Ancestral Robe Top", "cox", 5));
		items.add(new CatalogItem("cox-kit", "Kit/Dust", "cox", 1));

		items.add(new CatalogItem("tob-scythe", "Scythe of Vitur", "tob", 20));
		items.add(new CatalogItem("tob-sang", "Sanguinesti Staff", "tob", 6));
		items.add(new CatalogItem("tob-rapier", "Ghrazi Rapier", "tob", 6));
		items.add(new CatalogItem("tob-kit", "Kit/Dust", "tob", 1));

		items.add(new CatalogItem("toa-shadow", "Tumeken's Shadow", "toa", 20));
		items.add(new CatalogItem("toa-fang", "Osmumten's Fang", "toa", 2));
		items.add(new CatalogItem("toa-ward", "Elidinis' Ward", "toa", 1));
		items.add(new CatalogItem("toa-masori-body", "Masori Body", "toa", 5));
		return items;
	}

	@Before
	public void setUp() throws IOException
	{
		// new Gson() is fine in src/test; the Plugin Hub packager only scans src/main.
		AliasResource.Loaded baked = AliasResource.load(new Gson());
		catalog = DropCatalog.build(seedItems(), Collections.emptyMap(), baked.getAliases(),
			baked.getIgnored());
	}

	private void assertResolves(String inGameName, String expectedId)
	{
		assertTrue("no catalog match for: " + inGameName, catalog.lookup(inGameName).isPresent());
		assertEquals(inGameName, expectedId, catalog.lookup(inGameName).get().getDropItemId());
	}

	@Test
	public void resolvesPlainSentenceCaseNames()
	{
		assertResolves("Twisted bow", "cox-tbow");
		assertResolves("Elder maul", "cox-maul");
		assertResolves("Dragon claws", "cox-claws");
		assertResolves("Ancestral robe top", "cox-anc-top");
		assertResolves("Ghrazi rapier", "tob-rapier");
		assertResolves("Masori body", "toa-masori-body");
	}

	@Test
	public void resolvesKodaiInsignia()
	{
		// The single most important alias: CoX drops the insignia, never the wand. Without this,
		// every Kodai in the event scores zero.
		assertResolves("Kodai insignia", "cox-kodai");
	}

	@Test
	public void stripsChargeSuffixes()
	{
		assertResolves("Scythe of Vitur (uncharged)", "tob-scythe");
		assertResolves("Sanguinesti staff (uncharged)", "tob-sang");
		assertResolves("Tumeken's shadow (uncharged)", "toa-shadow");
	}

	@Test
	public void resolvesElidinisWardWithoutAnyBrokenSuffix()
	{
		// There is no "Elidinis' ward (broken)" item; the ToA drop broadcasts as the plain name.
		assertResolves("Elidinis' ward", "toa-ward");
	}

	@Test
	public void kitAndDustResolveToTheCorrectRaid()
	{
		// "Kit/Dust" exists once per raid, so name alone is ambiguous. Only the alias knows.
		assertResolves("Metamorphic dust", "cox-kit");
		assertResolves("Twisted ancestral colour kit", "cox-kit");
		assertResolves("Twisted ancestral color kit", "cox-kit");

		assertResolves("Sanguine dust", "tob-kit");
		assertResolves("Holy ornament kit", "tob-kit");
		assertResolves("Sanguine ornament kit", "tob-kit");
	}

	@Test
	public void resolvesBothSpellingsOfDexterousScroll()
	{
		assertResolves("Dexterous prayer scroll", "cox-dex");
		assertResolves("Dextrous prayer scroll", "cox-dex");
	}

	@Test
	public void doesNotStripBuiltUpgradeSuffixes()
	{
		// These are upgrades the player made, never raid drops. Scoring them would award points
		// for a cosmetic recolour.
		assertFalse(catalog.lookup("Osmumten's fang (or)").isPresent());
		assertFalse(catalog.lookup("Masori body (f)").isPresent());
		assertFalse(catalog.lookup("Elidinis' ward (f)").isPresent());
	}

	@Test
	public void knownNonScoringRaidLootIsRecognisedAsIgnored()
	{
		assertTrue(catalog.isKnownIgnored("Olmlet"));
		assertTrue(catalog.isKnownIgnored("Dark relic"));
		assertTrue(catalog.isKnownIgnored("Lil' Zik"));
		// ToA upgrade items: deliberately not scored, because the catalog has no ToA Kit/Dust row.
		assertTrue(catalog.isKnownIgnored("Thread of elidinis"));
		assertTrue(catalog.isKnownIgnored("Breach of the scarab"));
		assertTrue(catalog.isKnownIgnored("Eye of the corruptor"));
		assertTrue(catalog.isKnownIgnored("Jewel of the sun"));

		assertFalse(catalog.isKnownIgnored("Twisted bow"));
	}

	@Test
	public void toaUpgradeItemsDoNotScore()
	{
		assertFalse(catalog.lookup("Thread of elidinis").isPresent());
		assertFalse(catalog.lookup("Breach of the scarab").isPresent());
	}

	@Test
	public void serverAliasOverridesTheBakedInTable()
	{
		// The server map is authoritative so a rename can be fixed with a deploy, not a release.
		Map<String, String> serverAlias = new HashMap<>();
		serverAlias.put("kodai insignia", "cox-maul");

		DropCatalog overridden = DropCatalog.build(seedItems(), serverAlias,
			Collections.emptyMap(), Collections.emptyList());

		assertEquals("cox-maul", overridden.lookup("Kodai insignia").get().getDropItemId());
	}

	@Test
	public void unknownItemsDoNotResolve()
	{
		assertFalse(catalog.lookup("Bandos chestplate").isPresent());
		assertFalse(catalog.lookup("").isPresent());
		assertFalse(catalog.lookup(null).isPresent());
	}
}

package com.bingobrazilchat.chat;

import java.util.Optional;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Broadcast wording is the part of this plugin most likely to be wrong, and a mismatch fails
 * silently (a drop simply never scores). These cases pin down every shape observed in the wild.
 */
public class BroadcastParserTest
{
	private static ParsedBroadcast parsed(String line)
	{
		Optional<ParsedBroadcast> p = BroadcastParser.parse(line);
		assertTrue("expected a match for: " + line, p.isPresent());
		return p.get();
	}

	@Test
	public void parsesRaidSpecialLoot()
	{
		ParsedBroadcast p = parsed("Zezinho received special loot from a raid: Twisted bow.");
		assertEquals(BroadcastKind.RAID_SPECIAL_LOOT, p.getKind());
		assertEquals("Zezinho", p.getRsn());
		assertEquals("Twisted bow", p.getItemName());
	}

	@Test
	public void parsesRaidSpecialLootWithoutTrailingPeriod()
	{
		// Both forms occur; the corpus has "Tumeken's shadow (uncharged)" with no full stop.
		ParsedBroadcast p = parsed(
			"Zezinho Two received special loot from a raid: Tumeken's shadow (uncharged)");
		assertEquals("Zezinho Two", p.getRsn());
		assertEquals("Tumeken's shadow (uncharged)", p.getItemName());
	}

	@Test
	public void chargeSuffixSurvivesParsingAndIsNotEatenByTheValueGroup()
	{
		// The optional (value) group accepts digits and commas only, precisely so it can never
		// swallow a legitimate parenthetical like "(uncharged)".
		ParsedBroadcast p = parsed(
			"Zezinho received special loot from a raid: Scythe of Vitur (uncharged).");
		assertEquals("Scythe of Vitur (uncharged)", p.getItemName());
		assertEquals(-1L, p.getValueGp());
	}

	@Test
	public void parsesRaidSpecialLootCarryingAValue()
	{
		// Sources disagree on whether this line carries a GE value, so we accept both.
		ParsedBroadcast p = parsed(
			"Karambtwo received special loot from a raid: Twisted bow (1,680,988,483)");
		assertEquals("Twisted bow", p.getItemName());
		assertEquals(1_680_988_483L, p.getValueGp());
	}

	@Test
	public void stripsColourTags()
	{
		ParsedBroadcast p = parsed(
			"<col=ef20ff>Zezinho received special loot from a raid: Kodai insignia.</col>");
		assertEquals("Zezinho", p.getRsn());
		assertEquals("Kodai insignia", p.getItemName());
	}

	@Test
	public void handlesNonBreakingSpaceInTwoWordName()
	{
		// OSRS renders display names with U+00A0. Without the fold in Sanitizer, this never matches.
		ParsedBroadcast p = parsed(
			"Fn Junior received special loot from a raid: Elidinis' ward.");
		assertEquals("Fn Junior", p.getRsn());
		assertEquals("Elidinis' ward", p.getItemName());
	}

	@Test
	public void handlesTypographicApostrophe()
	{
		ParsedBroadcast p = parsed(
			"Zezinho received special loot from a raid: Osmumten’s fang.");
		assertEquals("Osmumten's fang", p.getItemName());
	}

	@Test
	public void stripsMetadataPrefixHiddenBehindAColourSpan()
	{
		ParsedBroadcast p = parsed(
			"<col=ef20ff>CA_ID:112|Zezinho received special loot from a raid: Dragon claws.</col>");
		assertEquals("Zezinho", p.getRsn());
		assertEquals("Dragon claws", p.getItemName());
	}

	@Test
	public void parsesValueDropWithCoinsAndSource()
	{
		// Without handling the "from <Source>" clause, the lazy item group swallows the whole tail.
		ParsedBroadcast p = parsed(
			"Zezinho received a drop: Voidwaker blade (39,648,370 coins) from Vet'ion.");
		assertEquals(BroadcastKind.VALUE_DROP, p.getKind());
		assertEquals("Voidwaker blade", p.getItemName());
		assertEquals(39_648_370L, p.getValueGp());
		assertEquals("Vet'ion", p.getSource());
	}

	@Test
	public void parsesValueDropWithQuantity()
	{
		ParsedBroadcast p = parsed("Zezinho received a drop: 587 x Cannonball (111,530 coins).");
		assertEquals("Cannonball", p.getItemName());
		assertEquals(587, p.getQuantity());
	}

	@Test
	public void parsesValueDropWithoutSource()
	{
		ParsedBroadcast p = parsed("Zezinho received a drop: Abyssal whip (1,456,814 coins).");
		assertEquals("Abyssal whip", p.getItemName());
		assertEquals(null, p.getSource());
		assertEquals(1, p.getQuantity());
	}

	@Test
	public void rejectsUnrelatedLines()
	{
		assertFalse(BroadcastParser.parse("Zezinho has logged in.").isPresent());
		assertFalse(BroadcastParser.parse("").isPresent());
		assertFalse(BroadcastParser.parse(null).isPresent());
	}

	@Test
	public void rejectsAnImpossiblyLongName()
	{
		// A greedy leading group would happily match rubbish here; the RSN validity check is what
		// stops a malformed line becoming a submission.
		assertFalse(BroadcastParser.parse(
			"This is far too long to be a name received a drop: Twisted bow.").isPresent());
	}

	@Test
	public void flagsUnparsedDropLookalikesForTheDebugLog()
	{
		assertTrue(BroadcastParser.looksLikeUnparsedDrop(
			"Zezinho received something entirely new: Twisted bow."));
		assertFalse(BroadcastParser.looksLikeUnparsedDrop(
			"Zezinho received special loot from a raid: Twisted bow."));
		assertFalse(BroadcastParser.looksLikeUnparsedDrop("Zezinho has logged in."));
	}
}

package com.bingobrazilchat.event;

import java.time.Instant;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class EventWindowTest
{
	private static final Instant START = Instant.parse("2026-09-15T00:00:00Z");
	private static final Instant END = Instant.parse("2026-09-30T00:00:00Z");

	private static EventWindow window(Instant start, Instant end)
	{
		return new EventWindow("event-1", "Test Event", start, end);
	}

	@Test
	public void closedBeforeStart()
	{
		EventWindow w = window(START, END);
		assertFalse(w.isOpen(START.minusSeconds(1)));
		assertTrue(w.isBeforeStart(START.minusSeconds(1)));
	}

	@Test
	public void openOnTheBoundaries()
	{
		EventWindow w = window(START, END);
		assertTrue(w.isOpen(START));
		assertTrue(w.isOpen(END));
	}

	@Test
	public void closedAfterEnd()
	{
		EventWindow w = window(START, END);
		assertFalse(w.isOpen(END.plusSeconds(1)));
		assertTrue(w.isAfterEnd(END.plusSeconds(1)));
	}

	@Test
	public void nullBoundsMeanUnbounded()
	{
		// events.start_date and end_date are both nullable. A missing bound must mean "no limit in
		// that direction", not "closed" -- otherwise an event with no end date would never score.
		assertTrue(window(null, END).isOpen(START.minusSeconds(100_000)));
		assertTrue(window(START, null).isOpen(END.plusSeconds(100_000)));
		assertTrue(window(null, null).isOpen(Instant.now()));
	}

	@Test
	public void keepsItsIdentity()
	{
		assertEquals("event-1", window(START, END).getEventId());
		assertEquals("Test Event", window(START, END).getName());
	}
}

package com.bingobrazilchat.submit;

import com.bingobrazilchat.api.ApiException;
import java.util.Random;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Retry classification is the guard against one misconfigured token turning a whole clan into a
 * retry loop against the site. A false "retryable" here is a self-inflicted outage.
 */
public class BackoffTest
{
	@Test
	public void transportFailuresRetry()
	{
		assertTrue(Backoff.shouldRetry(ApiException.transport("connection reset")));
	}

	@Test
	public void serverErrorsRetry()
	{
		assertTrue(Backoff.shouldRetry(ApiException.fromStatus(500, "", 0)));
		assertTrue(Backoff.shouldRetry(ApiException.fromStatus(502, "", 0)));
		assertTrue(Backoff.shouldRetry(ApiException.fromStatus(503, "", 0)));
		assertTrue(Backoff.shouldRetry(ApiException.fromStatus(504, "", 0)));
	}

	@Test
	public void rateLimitingRetries()
	{
		assertTrue(Backoff.shouldRetry(ApiException.fromStatus(429, "", 30)));
	}

	@Test
	public void clientErrorsAreTerminal()
	{
		// These will never improve by asking again, and a bad shared token is a 401.
		assertFalse(Backoff.shouldRetry(ApiException.fromStatus(400, "", 0)));
		assertFalse(Backoff.shouldRetry(ApiException.fromStatus(401, "", 0)));
		assertFalse(Backoff.shouldRetry(ApiException.fromStatus(403, "", 0)));
		assertFalse(Backoff.shouldRetry(ApiException.fromStatus(404, "", 0)));
		assertFalse(Backoff.shouldRetry(ApiException.fromStatus(413, "", 0)));
	}

	@Test
	public void authFailuresAreIdentifiable()
	{
		// The panel says "check your token" only for these.
		assertTrue(ApiException.fromStatus(401, "", 0).isAuthFailure());
		assertTrue(ApiException.fromStatus(403, "", 0).isAuthFailure());
		assertFalse(ApiException.fromStatus(500, "", 0).isAuthFailure());
	}

	@Test
	public void retryAfterWins()
	{
		Backoff backoff = new Backoff(new Random(1));
		assertEquals(30_000L, backoff.delayMillis(0, 30));
	}

	@Test
	public void retryAfterIsStillCapped()
	{
		Backoff backoff = new Backoff(new Random(1));
		assertEquals(Backoff.CAP_MS, backoff.delayMillis(0, 60 * 60));
	}

	@Test
	public void delayStaysWithinTheCeilingForTheAttempt()
	{
		Backoff backoff = new Backoff(new Random(42));
		for (int attempt = 0; attempt < 12; attempt++)
		{
			long delay = backoff.delayMillis(attempt, 0);
			assertTrue("attempt " + attempt, delay >= 0);
			assertTrue("attempt " + attempt, delay <= Backoff.ceilingFor(attempt));
			assertTrue("attempt " + attempt, delay <= Backoff.CAP_MS);
		}
	}

	@Test
	public void ceilingGrowsThenSaturates()
	{
		assertEquals(Backoff.BASE_MS, Backoff.ceilingFor(0));
		assertEquals(Backoff.BASE_MS * 2, Backoff.ceilingFor(1));
		assertEquals(Backoff.BASE_MS * 4, Backoff.ceilingFor(2));
		assertEquals(Backoff.CAP_MS, Backoff.ceilingFor(30));
		// Guards the left-shift overflow: a large attempt count must not wrap to a tiny delay.
		assertEquals(Backoff.CAP_MS, Backoff.ceilingFor(Integer.MAX_VALUE));
	}

	@Test
	public void jitterSpreadsRetriesOut()
	{
		// Without jitter every client in the clan would retry in lockstep after an outage and hit
		// the site as one wave.
		Backoff backoff = new Backoff(new Random(7));
		long first = backoff.delayMillis(5, 0);
		boolean sawDifferent = false;
		for (int i = 0; i < 20 && !sawDifferent; i++)
		{
			sawDifferent = backoff.delayMillis(5, 0) != first;
		}
		assertTrue("expected jittered delays to differ", sawDifferent);
	}
}

package com.bingobrazilchat.submit;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The dedupe key is what stops one clan broadcast becoming N scored drops. Because
 * leaderboard_teams sums points, a key that differs between two clients is not a cosmetic bug --
 * it is a duplicated Twisted Bow worth 20 phantom points.
 */
public class DedupeKeyTest
{
	private static final String EVENT = "11111111-2222-3333-4444-555555555555";
	private static final String ITEM = "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee";

	@Test
	public void isStableForTheSameDrop()
	{
		assertEquals(DedupeKey.of(EVENT, "Zezinho", ITEM), DedupeKey.of(EVENT, "Zezinho", ITEM));
	}

	@Test
	public void ignoresClockDifferencesBetweenClients()
	{
		// There is no timestamp in the key at all, precisely so that clients whose clocks disagree
		// by minutes still agree on the key. This test exists to stop anyone adding one.
		String a = DedupeKey.of(EVENT, "Zezinho", ITEM);
		Thread.yield();
		String b = DedupeKey.of(EVENT, "Zezinho", ITEM);
		assertEquals(a, b);
	}

	@Test
	public void agreesAcrossEverySpellingOfOneName()
	{
		// Twenty clients may render the dropper's name differently -- NBSP, hyphen, case. They must
		// still land on one key, or the herd never collapses.
		String canonical = DedupeKey.of(EVENT, "Fn Junior", ITEM);
		assertEquals(canonical, DedupeKey.of(EVENT, "fn junior", ITEM));
		assertEquals(canonical, DedupeKey.of(EVENT, "FN-JUNIOR", ITEM));
		assertEquals(canonical, DedupeKey.of(EVENT, "Fn_Junior", ITEM));
		assertEquals(canonical, DedupeKey.of(EVENT, " Fn  Junior ", ITEM));
	}

	@Test
	public void differsByPlayer()
	{
		assertNotEquals(DedupeKey.of(EVENT, "Zezinho", ITEM), DedupeKey.of(EVENT, "Someone", ITEM));
	}

	@Test
	public void differsByItem()
	{
		assertNotEquals(DedupeKey.of(EVENT, "Zezinho", ITEM),
			DedupeKey.of(EVENT, "Zezinho", "ffffffff-bbbb-cccc-dddd-eeeeeeeeeeee"));
	}

	@Test
	public void differsByEvent()
	{
		// Otherwise a drop in one event would suppress the same drop in the next one.
		assertNotEquals(DedupeKey.of(EVENT, "Zezinho", ITEM),
			DedupeKey.of("99999999-2222-3333-4444-555555555555", "Zezinho", ITEM));
	}

	@Test
	public void isLowercaseHexOfTheRightLength()
	{
		// The server validates this shape, so a change to the digest would be rejected there.
		String key = DedupeKey.of(EVENT, "Zezinho", ITEM);
		assertEquals(64, key.length());
		assertTrue(key, key.matches("^[0-9a-f]{64}$"));
	}
}

package com.bingobrazilchat.util;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * These cases are deliberately the same ones asserted against {@code normalizeRsn} in the website's
 * {@code plugin-api.test.ts}. The two implementations must agree exactly: if they drift, clients
 * and server compute different dedupe keys and the broadcast herd stops collapsing.
 */
public class RsnUtilTest
{
	@Test
	public void lowercases()
	{
		assertEquals("zezinho", RsnUtil.normalizeForCompare("Zezinho"));
	}

	@Test
	public void treatsHyphenUnderscoreAndSpaceAsTheSameSeparator()
	{
		assertEquals("fn junior", RsnUtil.normalizeForCompare("Fn-Junior"));
		assertEquals("fn junior", RsnUtil.normalizeForCompare("Fn_Junior"));
		assertEquals("fn junior", RsnUtil.normalizeForCompare("Fn Junior"));
	}

	@Test
	public void collapsesRepeatedSeparatorsAndTrims()
	{
		assertEquals("fn junior", RsnUtil.normalizeForCompare("  Fn__Junior  "));
	}

	@Test
	public void handlesNullAndEmpty()
	{
		assertEquals("", RsnUtil.normalizeForCompare(null));
		assertEquals("", RsnUtil.normalizeForCompare("   "));
	}

	@Test
	public void acceptsRealNames()
	{
		assertTrue(RsnUtil.isValid("Zezinho"));
		assertTrue(RsnUtil.isValid("Fn Junior"));
		assertTrue(RsnUtil.isValid("A-B_c 123"));
		assertTrue(RsnUtil.isValid("123456789012"));
	}

	@Test
	public void rejectsNamesTheServerWouldReject()
	{
		// OSRS display names are at most 12 characters, and the server enforces the same rule.
		assertFalse(RsnUtil.isValid("1234567890123"));
		assertFalse(RsnUtil.isValid(""));
		assertFalse(RsnUtil.isValid(null));
		assertFalse(RsnUtil.isValid("bad<name>"));
	}
}
